(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c26"]=[{"id":"00004553","register_sub_id":"101","register_pk":"105543","name":"料亭河文主屋","kana":"りょうていかわぶんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市中区丸の内2-12-19","lat":35.17540704,"lng":136.90089876,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積325㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0156","desc":"江戸時代中期から続く名古屋屈指の老舗料亭の主屋。２階建，入母屋造，桟瓦葺で，１階東方に帳場や土間を配す以外は客室とする。座敷飾を備えた座敷や和風を基調とした洋間を廊下や鞘の間で適当な距離をおいて配し，格調高くゆとりのある接客空間を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004553"},{"id":"00004555","register_sub_id":"101","register_pk":"105545","name":"料亭河文新用亭及び渡廊下","kana":"りょうていかわぶんしんようていおよびわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市中区丸の内2-12-19","lat":35.17553631,"lng":136.90087655,"geo_status":"db","era":"昭和25～27","year":1950,"year_source":"converted","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積63㎡、渡廊下 木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0158","desc":"主屋北に建つ離れ。平屋建，入母屋造，桟瓦葺で，１０畳の座敷と５畳の鞘の間を南北に並べ，南・東・北３方に広縁を廻らす。南西に接続する渡廊下は，両下造，化粧屋根裏で，床は中央畳敷，両側板張とする。木柄の細い瀟洒な構えでくつろいだ接客空間を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004555"},{"id":"00004557","register_sub_id":"101","register_pk":"105547","name":"料亭河文厨房","kana":"りょうていかわぶんちゅうぼう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市中区丸の内2-12-19","lat":35.175491,"lng":136.90101997,"geo_status":"db","era":"昭和12／昭和25増築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造及び木造2階建、建築面積132㎡","structure_material":"鉄筋コンクリート造及び木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0160","desc":"主屋の北面東端部に接続する。鉄筋コンクリート造，２階建，陸屋根の主体部を中心に，南及び西に戦後復興された木造の下屋や廊下を付設する。主体部は装飾を廃した機能的で簡明な造りだが，内部の磁器タイル，鉄骨階段，滑り出しの窓などに時代の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004557"},{"id":"00004556","register_sub_id":"101","register_pk":"105546","name":"料亭河文用々亭","kana":"りょうていかわぶんようようてい","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市中区丸の内2-12-19","lat":35.17559566,"lng":136.90078872,"geo_status":"db","era":"昭和25～27","year":1950,"year_source":"converted","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0159","desc":"主屋北西に位置し渡廊下で連絡する。平屋，切妻造，桟瓦葺一部銅板葺で，６畳主室の南を幅１間弱の廊下とする。柱や桁に丸太を用い，掛込み天井等で変化に富んだ室内を構成し，各面とも大きく開口部を開き茶屋風に造る。小規模で簡素ながら瀟洒な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004556"},{"id":"00004586","register_sub_id":"101","register_pk":"105576","name":"麻吉旅館聚遠楼","kana":"あさきちりょかんじゅえんろう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町111","lat":34.47768486,"lng":136.72177576,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造3階一部2階建、瓦葺、建築面積195㎡","structure_material":"木造3階一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"24 － 0054","desc":"本館の西方に位置する。桁行７間半梁間４間半，南北棟，寄棟造，桟瓦葺の木造３階建と，桁行７間半梁間３間，南北棟，寄棟造，桟瓦葺の木造２階建を並列した構成。最上階西方に８畳３室を並べ，東北隅に２１畳大の「聚遠楼」を置く。麻吉旅館の目印的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004586"},{"id":"00004585","register_sub_id":"101","register_pk":"105575","name":"麻吉旅館土蔵","kana":"あさきちりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町109-3","lat":34.477493,"lng":136.722122,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造3階一部2階建、瓦葺、建築面積72㎡","structure_material":"土蔵造3階一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"24 － 0053","desc":"本館の東南方に位置し，曲がった坂道に沿って棟を振って建つ。桁行３間梁間３間規模，切妻造，桟瓦葺，外観簓子下見板張の３階建土蔵で，本館寄りに桁行４間規模，２階建の蔵前部を持ち，本館の２階レベルに戸口を開ける。現在は麻吉旅館の資料館として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004585"},{"id":"00004584","register_sub_id":"101","register_pk":"105574","name":"麻吉旅館本館","kana":"あさきちりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町109-3","lat":34.477612,"lng":136.722,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造3階一部2階建、瓦葺、建築面積273㎡","structure_material":"木造3階一部2階建","registered":"2005.02.09(平成17.02.09)","register_no":"24 － 0052","desc":"内宮と外宮を結ぶ参宮道から東に入った傾斜地に位置する。坂道沿いに建つ寄棟造，桟瓦葺の木造３階建で，３階に主玄関を置き，２階に厨房と住居，１階と３階に客室を配する。地形に合わせた変形平面と階段状の階層構成に対応した複雑な屋根構成に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004584"},{"id":"00004588","register_sub_id":"101","register_pk":"105578","name":"麻吉旅館前蔵","kana":"あさきちりょかんまえぐら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町108-2","lat":34.47748352,"lng":136.72200642,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"24 － 0056","desc":"本館南方，坂道を隔てた向かいの敷地に位置し，本館の３階レベルと空中廊下で連絡する別棟の内蔵的存在。桁行２間半梁間２間，切妻造，桟瓦葺の２階建土蔵で，本館や土蔵との間に通る坂道側は簓子下見板張とし，独特な坂道景観の構成要素になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004588"},{"id":"00010173","register_sub_id":"101","register_pk":"198006","name":"麻野館玄関棟","kana":"あさのかんげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市二見町茶屋537-10","lat":34.507966,"lng":136.781059,"geo_status":"db","era":"明治28／大正11頃改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造2階建、瓦葺、建築面積437㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0177","desc":"二見浦に面する二見旅館街のほぼ中央に位置する旅館建築。玄関棟は街道に面する入母屋造桟瓦葺で、周囲に庇を廻らす。一階に玄関、帳場、厨房、浴室等、二階に客室と従業員室を配する。正面西寄りに切妻破風の本玄関を付す。二見の和風旅館の特色を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010173"},{"id":"00010175","register_sub_id":"101","register_pk":"198008","name":"麻野館土蔵","kana":"あさのかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊勢市二見町茶屋537-10","lat":34.508034,"lng":136.780911,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0179","desc":"玄関棟と広間棟の間、中庭を挟んで西寄りに位置する二階建の土蔵。屋根は切妻造桟瓦葺とし、外壁は黒漆喰塗の鉢巻下部まで簓子下見板を張る。中庭側の窓の瓦庇は、螻羽に破風板を含む役物瓦を用い、熨斗両端に波紋の飾りを載せるなどアクセントを付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010175"},{"id":"00010174","register_sub_id":"101","register_pk":"198007","name":"麻野館広間棟","kana":"あさのかんひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市二見町茶屋537-10","lat":34.508158,"lng":136.781085,"geo_status":"db","era":"明治28／昭和12頃改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造3階建、瓦葺、建築面積312㎡","structure_material":"木造3階建","registered":"2014.10.07(平成26.10.07)","register_no":"24 － 0178","desc":"玄関棟の奥に位置する旅館建築。北は海岸に面し、海岸への裏口が設けられている。一階と三階を客室とし、二階に客室のほか八〇畳の大広間を設ける。大広間は折上格天井で西面中央にトコ、左右に違棚と付書院を並べる。建具や欄間などに精緻な細工を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010174"},{"id":"00002265","register_sub_id":"101","register_pk":"103255","name":"伊勢河崎商人館北蔵二","kana":"いせかわさきしょうにんかんきたぐらに","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.49693398,"lng":136.71748751,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積102㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0034","desc":"伊勢河崎商人館のもとである小川酒店は老舗の酒卸業で，元禄年間の創業といわれる。北蔵二は酒蔵で，敷地の北側，北蔵一の西側に接するよう並んで建つ。切妻造・本瓦葺の屋根で，平屋建の前室と２階建の後室からなり，前室を比較的広くとる形態に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002265"},{"id":"00002259","register_sub_id":"101","register_pk":"103249","name":"伊勢河崎商人館主屋","kana":"いせかわさきしょうにんかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496567,"lng":136.717621,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0028","desc":"伊勢河崎商人館は河岸問屋街の河崎にある旧株式会社小川商店の一連の施設。主屋は，２階建，切妻造・妻入で，屋根は本瓦葺である。正面が街路に対して鍵型に突き出ているため，壁面を下見板で囲った特徴ある外観と相俟って，独特な景観を創り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002259"},{"id":"00002261","register_sub_id":"101","register_pk":"103251","name":"伊勢河崎商人館南蔵一","kana":"いせかわさきしょうにんかんみなみぐらいち","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.49651,"lng":136.717743,"geo_status":"db","era":"慶応3","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積66㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0030","desc":"河崎は勢田川沿いに形成された河岸問屋街。街路を挟んで主屋の対面に建つ３棟の土蔵は，背面が勢田川に面している。東端にある南蔵一は２階建，切妻造・妻入で，不整形な敷地のため，平面は菱形であるが，状態は良好である。棟木に慶応３年の墨書がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002261"},{"id":"00002263","register_sub_id":"101","register_pk":"103253","name":"伊勢河崎商人館南蔵三","kana":"いせかわさきしょうにんかんみなみぐらさん","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496399,"lng":136.717621,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積41㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0032","desc":"南蔵三ももと酒蔵で，南蔵二の西側にほぼ並行して建つ。桁行は南蔵二とほぼ同規模だが，梁間が小さい。切妻造・本瓦葺で，北妻面の庇は南蔵二と共有し，壁面は黒染の下見板張。勢田川に面して３棟の蔵が並ぶ景観は，舟運で栄えた町の歴史をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002263"},{"id":"00002262","register_sub_id":"101","register_pk":"103252","name":"伊勢河崎商人館南蔵二","kana":"いせかわさきしょうにんかんみなみぐらに","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市河崎2-25-32","lat":34.496429,"lng":136.717682,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積81㎡","structure_material":"土蔵造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"24 － 0031","desc":"主屋の対面に建つ３棟の土蔵のうち，南蔵二はその中央にある。３棟の内，規模が最も大きく，鬼瓦に明治２５年の銘がある。もとは酒蔵で，切妻造・本瓦葺。丁寧な野面石積の基礎上に建ち，北妻面に戸口を設け庇をつけ，壁面は黒染の下見板張で，重厚感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002262"},{"id":"00009623","register_sub_id":"101","register_pk":"194619","name":"一乃湯本館","kana":"いちのゆほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市上野西日南町1761他","lat":34.76185553,"lng":136.12978942,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0156","desc":"前庭を挟んで建つ。木造二階建、入母屋造妻入、桟瓦葺で、唐破風屋根の玄関を張出す。一階は脱衣所、二階は湯上りの休憩所として座敷を配す。全体は和風の意匠だが、浴場入口壁にはテラコッタやアーチなど洋風の意匠を見せる。上野城下町の歴史的景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009623"},{"id":"00009624","register_sub_id":"101","register_pk":"194620","name":"一乃湯門","kana":"いちのゆもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊賀市上野西日南町1761他","lat":34.76172942,"lng":136.12984177,"geo_status":"db","era":"大正15／昭和25改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"石造、間口2.1m、柵付","structure_material":"石造","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0157","desc":"本館正面の通りに面して建つ。花崗岩の石柱と鉄製の両開き門扉、両脇柱と鉄柵よりなる。門の上部には昭和二五年一乃湯開業時に設置された一乃湯の名前と温泉マークをかたどったネオン管の看板が取り付く。上野城下町の当時の銭湯文化の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009624"},{"id":"00009027","register_sub_id":"101","register_pk":"162387","name":"いとう旅館本館","kana":"いとうりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野桑町1481他","lat":34.75870975,"lng":136.13317307,"geo_status":"db","era":"明治後期／昭和33年増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積279㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0117","desc":"通りからやや後退した位置に建つ。木造二階建、建築面積279㎡。中庭を囲むように東棟と西棟、北棟が配される。十畳の主室には座敷飾りを構え、天井は格天井で格縁を黒漆塗とし、格板に鳳凰などを色彩豊かに描く。良質な茶屋建築の趣を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009027"},{"id":"00003677","register_sub_id":"101","register_pk":"104667","name":"上野文化センター","kana":"うえのぶんかせんたー","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県伊賀市上野中町3024","lat":34.76577313,"lng":136.1278026,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積84㎡","structure_material":"木造3階建","registered":"2003.12.01(平成15.12.01)","register_no":"24 － 0048","desc":"上野市の中心街に建つ木造３階建の商店建築。当初は倉庫として建設されたが，現在では事務所等に利用されている。外観は１階を花崗岩の石貼とし，２階以上はモルタル塗で，屋根は寄棟造鉄板葺である。上野市中心街の戦前の繁栄の様子を今に伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003677"},{"id":"00009985","register_sub_id":"101","register_pk":"196132","name":"栄楽館土蔵","kana":"えいらくかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野相生町2842","lat":34.76457535,"lng":136.13177735,"geo_status":"db","era":"明治6／平成6改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0175","desc":"南棟の南東隅に位置し、南北棟で建つ土蔵造二階建の蔵。西側に出入口を開き、土戸を建て込む。西面の腰には当地方で「鼓繋ぎ」と呼ぶ独特な海鼠壁状の漆喰塗を施す。鬼瓦には屋号の「栄楽」と入れる。瀟洒な装飾を施した土蔵で、往時の盛況を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009985"},{"id":"00009984","register_sub_id":"101","register_pk":"196131","name":"栄楽館東棟","kana":"えいらくかんひがしとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市上野相生町2842","lat":34.76465292,"lng":136.13172834,"geo_status":"db","era":"明治6／平成6改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0174","desc":"敷地北東側に南北棟で建つ。木造二階建で、一階には中庭に面して二室の座敷を配し、二階は一室の大広間とする。西面と北面に廻らされた縁からは、ガラス窓越しに庭園への眺望を得る。二階大広間は、トコ柱に丸太の曲り材を用いるなど、数寄屋風の意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009984"},{"id":"00009983","register_sub_id":"101","register_pk":"196130","name":"栄楽館南棟","kana":"えいらくかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊賀市上野相生町2842","lat":34.76453548,"lng":136.1316978,"geo_status":"db","era":"明治6／平成6改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0173","desc":"敷地南寄りに奥まって位置する。木造二階建で、一階には座敷三室と茶室が、二階には座敷二室が配される。欄間や高欄など随所に竹と扇を主題とした細工を施す。茶室では棹縁を放射状に配るなど、部屋ごとに天井の意匠を変え、変化に富む内装に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009983"},{"id":"00009986","register_sub_id":"101","register_pk":"196133","name":"栄楽館門及び塀","kana":"えいらくかんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野相生町2842","lat":34.76474194,"lng":136.13167774,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"門 木造、瓦葺、間口1.8m 塀 土塀、瓦葺、総延長14m","structure_material":"門 木造","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0176","desc":"道路に面して敷地の北辺を区画する塀で、西寄りに門を開く。上野城の石垣材と伝える大振りな石を腰高に積んで基礎とし、周囲に拳大の自然石を貼り付け、その上部に真壁造で瓦葺の塀を建てる。壁の上部には雲形状の絵様を象り、軽妙な佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009986"},{"id":"00012378","register_sub_id":"101","register_pk":"531702","name":"オーデン大門ビル（旧四日市銀行津支店）","kana":"おーでんだいもんびる（きゅうよっかいちぎんこうつしてん）","category":"産業3次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県津市大門254","lat":34.71883889,"lng":136.5122,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積238㎡、塔屋及び煙突付","structure_material":"鉄筋コンクリート造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"24-248","desc":"大門通りに東面して建つ旧四日市銀行津支店。鉄筋コンクリート造二階建で、屋上に塔屋と煙突を付ける。正面にイオニア式円柱の大オーダーを四本並べ、中央玄関上部にペディメントを戴く古典的で重厚な外観とする。地方における昭和初期銀行建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012378"},{"id":"00015201","register_sub_id":"101","register_pk":"530625","name":"数馬茶屋","kana":"かずまぢゃや","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊賀市小田町字新町裏1336他","lat":34.76759722,"lng":136.11993889,"geo_status":"db","era":"昭和4年／昭和36年移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"24 - 0333","desc":"伊賀越仇討で知られる鍵屋の辻の南側、公園内に東面して建つ休憩施設。入母屋造妻入桟瓦葺で北・東に庇を矩折に廻らす。内部は前土間で西に２室を配す。土間廻りは柱や天井材に古材を用いて古風にみせる。伊賀越仇討で待伏した茶屋を再現した記念碑的な施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015201"},{"id":"00006862","register_sub_id":"101","register_pk":"107844","name":"角屋旅館本館","kana":"かどやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県津市芸濃町椋本字愛宕町727","lat":34.809673,"lng":136.427032,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階一部平屋建、瓦葺、建築面積233㎡","structure_material":"木造2階一部平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"24 － 0068","desc":"旧伊勢別街道に南面して建つ。桁行７間半梁間５間半、切妻造桟瓦葺２階建で、背面西寄りに廊下や離れを出す。表側は西からアガリノマ、玄関土間、通り土間、８畳間を配し、２階には客室３室を並べる。揚戸や出格子等が旧伊勢別街道の旅籠の表構えを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006862"},{"id":"00007216","register_sub_id":"101","register_pk":"108198","name":"川地写真館","kana":"かわちしゃしんかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県名張市新町218-1","lat":34.61953,"lng":136.086227,"geo_status":"db","era":"大正10／昭和35頃・昭和45改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階一部3階建、瓦葺及び鉄板葺、建築面積102㎡","structure_material":"木造2階一部3階建","registered":"2008.07.08(平成20.07.08)","register_no":"24 － 0073","desc":"南西角地に建つ木造２階一部３階建である。東側道路を正面に、北東の３階建屋根に三角の妻壁を立ち上げ、パラペット隅に小塔形飾りを付ける。外壁はモルタル塗で、１、２階外壁のタイル貼は後の改修。当初の写場は２階西側で、屋根を一部ガラス張としていた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007216"},{"id":"00008294","register_sub_id":"101","register_pk":"133936","name":"旧伊藤伝七別邸さつき棟","kana":"きゅういとうでんしちべっていさつきとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県四日市市高砂町3492-67他","lat":34.96178978,"lng":136.63612431,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"24 － 0091","desc":"敷地の北西隅に建つ。建築面積５６㎡、木造平屋建、切妻造桟瓦葺で、十畳と六畳を並べて南面の庭側に縁をめぐらす。十畳では琵琶棚付のトコやトコ脇、付書院を設け、長押に半割丸太を用いるなど、瀟洒な意匠をもつ。開放的なつくりの離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008294"},{"id":"00013736","register_sub_id":"101","register_pk":"507741","name":"旧喜多藤艶秀亭","kana":"きゅうきたとえんしゅうてい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市本町116","lat":34.61864167,"lng":136.08824167,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 294","desc":"敷地の東に建つ。入口を表門とは別にする独立した客室。平屋建切妻造桟瓦葺。外壁は腰を割竹張、上部を色土で仕上げ、内部は和室四室に洋室を配す。各室毎に独立した玄関を設けて個別に出入りでき、意匠を違えた窓をつくる等趣向を凝らす。東辺の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013736"},{"id":"00013733","register_sub_id":"101","register_pk":"507738","name":"旧喜多藤大広間棟","kana":"きゅうきたとおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61848889,"lng":136.08791944,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積164㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 291","desc":"別館の西に建つ。北面して建ち、二階建入母屋造桟瓦葺。一階は座敷とダンスホールとし、ホールは洋風に中国風意匠を取入れた趣味性の高いつくり。二階は四四畳大広間で折上格天井に色漆喰壁を用いた豪奢な意匠。別館同様川沿いを掃出の開口として眺望を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013733"},{"id":"00013738","register_sub_id":"101","register_pk":"507743","name":"旧喜多藤表門","kana":"きゅうきたとおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61875556,"lng":136.087675,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造、瓦葺一部銅板葺、間口2.6m、左右袖塀付","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 296","desc":"初瀬街道に面して建つ薬医門。間口二・六メートルで左右に袖塀が付属する。本柱、控柱とも節を出した丸太材を用いて腕木を受け軒桁を渡す。屋根は入母屋造桟瓦葺一部銅板葺。軒天井は小丸太を敷並べた瀟洒な意匠。街道沿いにもと料亭旅館の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013738"},{"id":"00013735","register_sub_id":"101","register_pk":"507740","name":"旧喜多藤皐月寮","kana":"きゅうきたとさつきりょう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61848889,"lng":136.08775278,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 293","desc":"翠明荘から接続する茶室。平屋建切妻造桟瓦葺で東面に待合付設。茶室は四畳大で炉を切らず、西面一間半を床構えとし、皮付の曲材を用いた床柱や角竹、斜めの地袋で変化を付ける。南脇は半畳の点前座とし、天井は点前座と主室で網代と竹の棹縁に張り分ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013735"},{"id":"00013734","register_sub_id":"101","register_pk":"507739","name":"旧喜多藤翠明荘","kana":"きゅうきたとすいめいそう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61844444,"lng":136.08781667,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 292","desc":"大広間棟の西に建つ。平屋建入母屋造桟瓦葺で軒先を銅板葺として軽さを演出する。もとは居宅で、大広間と皐月寮へ続く渡り廊下を付属する。内部は一〇畳客間と洋室で、客間書院の格狭間形の下地窓や渡廊下袖壁の半円の切り欠きなど、数寄屋趣味が横溢する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013734"},{"id":"00013732","register_sub_id":"101","register_pk":"507737","name":"旧喜多藤別館","kana":"きゅうきたとべっかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61849722,"lng":136.08805278,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積209㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 290","desc":"名張川沿いのもと料亭旅館。北面して建ち、二階建切妻造桟瓦葺。一階は北をホールと調理場、南を客室とし、二階はホールの周囲に座敷を配する。二階は川沿いの間口いっぱいを掃出のガラス窓開口として眺望を誇る。料亭旅館の中心建物で川沿いの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013732"},{"id":"00013737","register_sub_id":"101","register_pk":"507742","name":"旧喜多藤便所棟","kana":"きゅうきたとべんじょとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県名張市本町118-1","lat":34.61861667,"lng":136.08796667,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"24 － 295","desc":"表門から入って正面に建つ別館の手前に位置する。平屋建入母屋造桟瓦葺で、別館と大広間棟からそれぞれ渡り廊下で接続する。便所と脱衣場・浴室からなり、廊下は柱を立てず、細丸太の垂木を並べて化粧屋根とし、人造石の手洗いを設ける。敷地の一点景を為す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013737"},{"id":"00012380","register_sub_id":"101","register_pk":"531704","name":"旧料理旅館九重別館","kana":"きゅうりょうりりょかんここのえべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和中","pref":"三重県","address":"三重県伊賀市上野西日南町1773他","lat":34.76145833,"lng":136.12976111,"geo_status":"db","era":"昭和24年頃","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"24-250","desc":"本館背面に離れて建つ小座敷。座敷二室を設けて各玄関を構え、接続部に共通の水回りを設ける。玄関や下屋に青瓦、壁に乱形石やタイルを用い、内部は大壁とし、新興数寄屋風の意匠で仕上げる。本館とともに伝統木造の料理旅館の姿をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012380"},{"id":"00012379","register_sub_id":"101","register_pk":"531703","name":"旧料理旅館九重本館","kana":"きゅうりょうりりょかんここのえほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊賀市上野西日南町1773他","lat":34.7615,"lng":136.1299,"geo_status":"db","era":"大正13年頃／昭和18年頃増築","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積317㎡","structure_material":"木造2階一部3階建","registered":"2018.05.10(平成30.05.10)","register_no":"24-249","desc":"旧城下の町人地にあり、東西通りの敷地の背面に南北通りの敷地を併せたＴ字形の敷地に建つ。本館は従前の町家を改修したもので、東西通りは町家の外観を残しつつ南北通りは前庭をもつ屋敷風として趣を異にする。城下の歴史と変遷を物語る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012379"},{"id":"00012381","register_sub_id":"101","register_pk":"531705","name":"旧料理旅館九重門及び塀","kana":"きゅうりょうりりょかんここのえもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊賀市上野西日南町1773他","lat":34.76145,"lng":136.13006667,"geo_status":"db","era":"昭和18年頃","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"門 木造、瓦葺、間口3.1m 塀 木造、瓦葺、総延長14m","structure_material":"門 木造","registered":"2018.05.10(平成30.05.10)","register_no":"24-251","desc":"南北通りの敷地正面と南隣の敷地境を区切る塀と正面中央に開いた切妻造の門。真壁造の中塗仕上、腰羽目板張とし、敷地境は大和塀とする。門は軒の低い棟門で、両側に割竹の袖塀を付ける。本館とともに伝統木造の料理旅館の表構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012381"},{"id":"00012938","register_sub_id":"101","register_pk":"368019","name":"熊野古道おもてなし館（旧杤尾家住宅店舗兼主屋）","kana":"くまのこどうおもてなしかん（きゅうとちおけじゅうたくてんぽけんしゅおく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県熊野市木本町字関舟町204","lat":33.89030556,"lng":136.10396667,"geo_status":"db","era":"明治中期／平成26年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"24 － 273","desc":"市中心部のもと小間物問屋。熊野街道に北面して建つ切妻造桟瓦葺つし二階建で、正面下屋上を黒漆喰塗として中央に白漆喰枠の虫籠窓を穿ち、東側に背面納戸付の袖塀を付す。内部は改変があるが、西奥の座敷に当初の姿を残す。街道の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012938"},{"id":"00008497","register_sub_id":"101","register_pk":"134893","name":"桑名市石取会館（旧桑名信用金庫京町支店）","kana":"くわなしいしどりかいかん(きゅうくわなしんようきんこきょうまちしてん)","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県桑名市京町16","lat":35.06359908,"lng":136.69427903,"geo_status":"db","era":"大正14年／平成3年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積168㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"24 － 0101","desc":"市の中心、京町と職人町の通りが交叉する角地に建つ。鉄筋コンクリート造二階建で、北に旧金庫室を付ける。東南角を曲面とし、縦長の窓を二層を通して開ける。南・東面は簡潔で幾何学的な柱型を現し、縦長窓上部には歯飾りを施し、陰影の深い意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008497"},{"id":"00010614","register_sub_id":"101","register_pk":"201188","name":"小西萬金丹本舗内蔵","kana":"こにしまんきんたんほんぽうちくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県伊勢市八日市場町8","lat":34.491087,"lng":136.702054,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0205","desc":"店舗兼主屋の北西隅に接続し、東西棟で建つ。桁行二間梁間二間、土蔵造二階建、切妻造本瓦葺である。外壁は頂部に鉢巻を廻らし、高く簓子下見板を張る。南面に戸口を開いて漆喰塗の土戸を吊る。商品の萬金丹や製薬道具を納めた蔵で、敷地後方の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010614"},{"id":"00010615","register_sub_id":"101","register_pk":"201189","name":"小西萬金丹本舗外蔵","kana":"こにしまんきんたんほんぽそとくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市八日市場町7","lat":34.491101,"lng":136.70229,"geo_status":"db","era":"安永8年（1779）","year":1779,"year_source":"db","year_min":1779,"year_max":1779,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0206","desc":"店舗兼主屋の北東方に南北棟で建ち、土蔵造二階建、切妻造本瓦葺である。南正面を戸口として土戸を開き、桟瓦葺の下屋を設ける。外壁は頂部に鉢巻を廻らして簓子下見板を張る。二階は換気窓のみ設ける。着物などを納めていた家財蔵で、商家の屋敷構えを創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010615"},{"id":"00010613","register_sub_id":"101","register_pk":"201187","name":"小西萬金丹本舗店舗兼主屋","kana":"こにしまんきんたんほんぽてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊勢市八日市場町8","lat":34.49104,"lng":136.702105,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積144㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"24－0204","desc":"外宮門前の通り沿いに南面して建つ。起り付の切妻造妻入で、正面に本瓦葺の下屋を設ける。外壁全体を簓子下見板張とし、二階正面に出格子をたてる。内部は中央のミセの奥に座敷を並べ、東に茶室、西に坪庭を配する。伊勢町家の特徴を示す大型の商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010613"},{"id":"00009619","register_sub_id":"101","register_pk":"194615","name":"佐野家住宅石垣","kana":"さのけじゅうたくいしがき","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県松阪市飯南町深野字田之浦3490-1","lat":34.47530963,"lng":136.40986743,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、延長48m","structure_material":"石造","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0152","desc":"敷地の北から東辺を囲む。折曲り延長四八メートルで、上部は土塀や生垣とする。当地域でよく見られる、玉石を野面積みとした石垣で、北面の一部では石垣下部に窪みを設けて湧水溜とするなど特徴的なつくりにも変化を見せる。伝統的な敷地景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009619"},{"id":"00009618","register_sub_id":"101","register_pk":"194614","name":"佐野家住宅小蔵","kana":"さのけじゅうたくこくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県松阪市飯南町深野字田之浦3490-1","lat":34.47530616,"lng":136.4100717,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積7.2㎡","structure_material":"土蔵造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0151","desc":"敷地の北方に南北棟で建つ。切妻造桟瓦葺、妻入で南面の戸口に庇を付ける。棟木と桁に流し板を渡して屋根野地とする。道具類の収納に用いられた蔵で、桁行四・八メートル梁間一・五メートルと小規模ながら、土塀、石垣とともに屋敷構えの境界を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009618"},{"id":"00009617","register_sub_id":"101","register_pk":"194613","name":"佐野家住宅主屋","kana":"さのけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯南町深野字田之浦3490-1","lat":34.47492307,"lng":136.40976713,"geo_status":"db","era":"明治前期／明治中期増築・昭和11・昭和37改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0150","desc":"佐野翠香堂の屋号で薬種業を営んだ家の主屋。櫛田川北岸の和歌山街道に南面する。切妻造桟瓦葺、東に通り土間、西に食違二列六間取の座敷を配す主体部と、東に接続し、二室と縁が取付く東西棟の増築部からなる。主体部正面の建ちが低く当地域でも古式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009617"},{"id":"00009620","register_sub_id":"101","register_pk":"194616","name":"佐野家住宅土塀","kana":"さのけじゅうたくどべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県松阪市飯南町深野字田之浦3490-1","lat":34.4750959,"lng":136.41033353,"geo_status":"db","era":"明治頃","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治頃","structure":"土塀、瓦葺、延長16m、潜戸付","structure_material":"土塀","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0153","desc":"敷地東面の石垣上に築かれた土塀で、北側の六・四メートルに対し南側九・三メートルは棟を下げて、潜戸一所を開く。切妻造桟瓦葺で、軒裏まで漆喰塗込として鉢巻を廻らす。重厚な趣を見せ、小蔵、石垣とともに敷地の景観を整える要素の一つとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009620"},{"id":"00014854","register_sub_id":"101","register_pk":"519114","name":"清風亭客室棟","kana":"せいふうていきゃくしつとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県名張市鍛治町91","lat":34.618575,"lng":136.09006111,"geo_status":"db","era":"大正3年／昭和39年・平成26年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"24 - 0330","desc":"玄関棟の南に位置する客室棟は、名張川沿いに面する座敷棟。二階建切妻造桟瓦葺とし、一階は厨房と２室の座敷、二階は３室続きの座敷で東に床を構え、船底天井を張り、南に縁を通して川を望む開放的なつくり。大人数の宴席も対応可能な広間で時代相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014854"},{"id":"00014853","register_sub_id":"101","register_pk":"519113","name":"清風亭玄関棟","kana":"せいふうていげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県名張市鍛治町91","lat":34.61865556,"lng":136.09010278,"geo_status":"db","era":"大正3年／昭和39年・平成10年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"24 - 0329","desc":"市街地南方の鍛冶町にある料理旅館。通りに面した玄関棟は二階建切妻造平入の東西棟で、一階の戸口以外は出格子構えとし東寄りに土間、中央に階段と帳場を配す。二階は前後二列に部屋を配し、渡廊下で南の客室棟と接続。格子構えの外観が通りの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014853"},{"id":"00009023","register_sub_id":"101","register_pk":"162383","name":"中六店舗","kana":"なかろくてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県志摩市磯部町上之郷字上ノ里392他","lat":34.38041726,"lng":136.81022788,"geo_status":"db","era":"昭和4年／昭和後期改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積172㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0113","desc":"伊勢神宮の別宮伊雑宮の門前に位置する。木造二階建、建築面積１７２㎡。Ｌ字形棟の入母屋造桟瓦葺で、一階には小さく入母屋造の角屋を付設し、外観に変化を付ける。神社側に妻を見せ、二階は大きく掃き出し窓を設け、軽快で開放的な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009023"},{"id":"00014027","register_sub_id":"101","register_pk":"508287","name":"星出館主屋","kana":"ほしでかんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊勢市河崎二丁目156-3","lat":34.49481944,"lng":136.71410278,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積326㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"24 - 0311","desc":"勢田川水運で栄えた河崎の八間道路に西面する二階建旅館。入母屋造桟瓦葺の大屋根の下に庇を付し、斜行する道路に対して正面が雁行し、唐破風玄関を設けて賑やかな外観とする。客室は各々意匠を凝らし、中庭を跨ぐ二階橋を備える。近代の伊勢詣を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014027"},{"id":"00014028","register_sub_id":"101","register_pk":"508288","name":"星出館塀","kana":"ほしでかんへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県伊勢市河崎二丁目156-3","lat":34.49476667,"lng":136.714,"geo_status":"db","era":"昭和2年頃／平成30年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造、瓦葺、延長10m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"24 - 0312","desc":"主屋の西正面の南端に設けた塀。玄関南から敷地西辺を延びて、南西角で折れて主屋に取付く。自然石の基礎に節付丸太柱を立て、地長押で固め、漆喰壁に櫛形下地窓を開き、腰は竪板張とする。屋根は桟瓦葺、杉丸太の疎垂木の軒で、和風旅館の外観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014028"},{"id":"00013812","register_sub_id":"101","register_pk":"507774","name":"松井真珠店蔵","kana":"まついしんじゅてんくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"三重県","address":"三重県志摩市阿児町神明字カシコ733-4","lat":34.30776111,"lng":136.81893889,"geo_status":"db","era":"昭和26年／昭和61年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積26㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0298","desc":"店舗の北方、鉄筋コンクリート造二階建の商品蔵である。桟瓦葺の切妻屋根や出格子窓で土蔵風外観とする。入口は両開き鉄扉と片引戸、網戸で、窓は鉄扉とガラス戸の両開きである。内壁は杉板張で天井を白漆喰塗。賢島駅の向かいに特色ある景観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013812"},{"id":"00013811","register_sub_id":"101","register_pk":"507773","name":"松井真珠店店舗","kana":"まついしんじゅてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県志摩市阿児町神明字カシコ733-4","lat":34.30756389,"lng":136.81901389,"geo_status":"db","era":"昭和4年頃／昭和48年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"24 － 0297","desc":"賢島港に面する木造二階建の真珠販売店。寄棟造の桟瓦葺で南正面から東西両側面へ桟瓦葺下屋を廻す。二階手摺には松の図柄を彫抜く。一階は西半北寄りを床上の帳場とし、二階は階段西を六畳座敷、東を一二畳半の広間とする。当地の産業を象徴する店舗建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013811"},{"id":"00011147","register_sub_id":"101","register_pk":"205254","name":"八千代大広間棟","kana":"やちよおおひろまとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県松阪市殿町1295","lat":34.574695,"lng":136.528846,"geo_status":"db","era":"昭和初期／昭和32改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積249㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"24 - 0233","desc":"玄関棟の奥に棟を直交して建つ木造二階建。一階に三〇畳の広間など、二階には一一〇畳の大広間を配する。内部造作は昭和三二年の改修によるが、大広間の折上格天井や枝付の大木の床柱、瀟洒な欄間意匠など、当時の旅館建築における和風意匠の嗜好をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011147"},{"id":"00011146","register_sub_id":"101","register_pk":"205253","name":"八千代玄関棟","kana":"やちよげんかんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県松阪市殿町1295","lat":34.574629,"lng":136.529018,"geo_status":"db","era":"昭和初期／昭和32改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積215㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"24 - 0232","desc":"松坂旧城下で通りに東面する料理旅館。玄関棟はやや後退して建つ木造二階建で、東正面に入母屋造の妻を見せ、玄関を構える。一階にロビーなど、二階は中廊下沿いに客室を配する。客室は網代天井や古びを見せた材を用いるなど、室ごとに異なる意匠と趣をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011146"},{"id":"00011148","register_sub_id":"101","register_pk":"205255","name":"八千代鶴亀棟","kana":"やちよつるかめとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"三重県","address":"三重県松阪市殿町1295","lat":34.574533,"lng":136.529023,"geo_status":"db","era":"大正初期／昭和前期移築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"24 - 0234","desc":"玄関棟正面の南側に建つ木造平屋建。一〇畳の鶴の間と八畳の亀の間を南北に並べ、東西に縁を通す。小津家住宅時代の遺構とみられ、造作は玄関棟などと比べて古風な意匠をもつ。松坂城下において旧武家町が閑静な住宅地へと変遷した近代的変容の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011148"},{"id":"00009982","register_sub_id":"101","register_pk":"196129","name":"山口家住宅主屋","kana":"やまぐちけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県名張市上八町1495-6","lat":34.62521264,"lng":136.09125385,"geo_status":"db","era":"明治前期／昭和6・平成18改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積186㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0172","desc":"初瀬街道に南面する木造二階建町家で、後方に明治期の座敷部を残しつつ、正面側を昭和六年に建替えて旅館とした。正面中央に主玄関を開き、東側に出格子をたて、西側に脇玄関を開く。二階は小部屋を多数配し、正面に手摺を付ける。戦前の街路の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009982"},{"id":"00007748","register_sub_id":"101","register_pk":"108729","name":"大和屋店舗","kana":"やまとやてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市本町55","lat":34.61962575,"lng":136.08873443,"geo_status":"db","era":"江戸末期／昭和34・昭和43改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"24-0078","desc":"旧市街地を通る初瀬街道に北面して建つ。間口８．３ｍの木造つし２階建、切妻造平入桟瓦葺で正面に下屋庇を付ける。正面全面を開口とし、西半部を土間、東半部を床上とする。上部は白漆喰仕上げで虫籠窓を穿ち、屋根に越屋根を載せ、老舗らしい佇まいを呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007748"},{"id":"00010979","register_sub_id":"101","register_pk":"208949","name":"料理旅館梅家","kana":"りょうりりょかんうめや","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市平田374","lat":34.766555,"lng":136.213882,"geo_status":"db","era":"明治後期／大正8改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積113㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"24-0231","desc":"伊賀街道に北面して建つ料理旅館。二階建入母屋造平入で、一階は西を土間とする四間取の平面とし、二階は中廊下の左右に部屋を配する。一階正面外観は欄間付竪格子戸を並べ、天女と鷹の鬼瓦、東西脇塀の欄間の蝙蝠の意匠など要所にアクセントをつけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010979"},{"id":"00009025","register_sub_id":"101","register_pk":"162385","name":"旅館薫楽荘蔵","kana":"りょかんくんらくそうくら","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野桑町1474他","lat":34.75854356,"lng":136.13283674,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0115","desc":"主屋の西北に位置する。土蔵造二階建、桁行４．９ｍ梁間３．９ｍ。南北棟の切妻造桟瓦葺で、北妻は通りに面する。外壁は銅板張で腰を簓子下見板張とし、東面は腰海鼠壁で出入口を穿つ。通り側の腰壁は下見板張りとして、塀と連続的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009025"},{"id":"00009024","register_sub_id":"101","register_pk":"162384","name":"旅館薫楽荘本館","kana":"りょかんくんらくそうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野桑町1474他","lat":34.75850374,"lng":136.13294233,"geo_status":"db","era":"明治後期／昭和49年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積189㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0114","desc":"敷地の北寄りに、通りに北面して建つ。木造二階建、建築面積１８９㎡、切妻造桟瓦葺。一階に五室、二階に六室の座敷を設け、各室はトコや棚、欄間などで意匠を凝らす。玄関の装飾タイルや四阿風のホール天井、廊下の小壁など見所の多い建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009024"},{"id":"00009026","register_sub_id":"101","register_pk":"162386","name":"旅館薫楽荘門及び塀","kana":"りょかんくんらくそうもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市上野桑町1474他","lat":34.75859802,"lng":136.13295586,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長12m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"24 － 0116","desc":"通り沿いに設けられ、主屋との間に庭が設けられる。高さ３．３ｍ延長１２ｍの塀で、主屋正面に間口２．０ｍの門口を開き、前後に瓦庇をかけ、引き分け戸をたてる。塀は腰高に竪板を張り、小壁を黒漆喰仕上げとする。粋な雰囲気を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009026"},{"id":"00006863","register_sub_id":"101","register_pk":"107845","name":"旅館寿亭水雲閣","kana":"りょかんことぶきていすいうんかく","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県三重郡菰野町大字菰野8588","lat":35.01568672,"lng":136.445015,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、銅板葺、建築面積131㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"24 － 0069","desc":"三滝川南岸近くの小高い位置に、南北棟で建つ。桁行７間梁間４間半規模、入母屋造銅板葺の木造２階建で、各階とも主室１０畳と次の間８畳からなり、北・西・南の三方に入側をまわし、北・西面には高欄付の濡縁を付ける。主室は良材を用い、品格ある意匠に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006863"},{"id":"00003678","register_sub_id":"101","register_pk":"104668","name":"今津ヴォーリズ資料館（旧百卅三銀行今津支店）","kana":"いまづう゛ぉーりずしりょうかん（きゅうひゃくさんじゅうさんぎんこういまづしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県高島市今津町今津175","lat":35.40217363,"lng":136.03557204,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積84㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"25 － 0229","desc":"Ｗ.Ｍ.ヴォーリズの設計により銀行店舗として建てられた。ＲＣによる柱梁構造に，壁面を煉瓦積としている。外観は石積風の古典様式を基調とするが，比較的簡素にまとめる。昭和末期から図書館として利用され，平成１５年からは資料館として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003678"},{"id":"00009035","register_sub_id":"101","register_pk":"162395","name":"宇水理髪館店舗","kana":"うみずりはつかんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市河原3-103-2","lat":35.26507238,"lng":136.25564587,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0303","desc":"通りに南面して建ち、桁行４．５ｍ梁間１０ｍ、木造二階建、切妻造桟瓦葺である。正面のアーチ頂部にバリカン形をあしらい、左右にアカンサス模様を飾る。町家形式を踏襲しつつ正面を洋風意匠でまとめており、町並みのアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009035"},{"id":"00002634","register_sub_id":"101","register_pk":"103624","name":"大津魚忠","kana":"おおつうおちゅう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市京町2-404、405","lat":35.006599,"lng":135.865829,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造2階建、瓦葺、建築面積169㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0185","desc":"大津旧市街の中心に呉服商の住居として建てられた町家で，現在は料亭を営む。２階建，切妻造，平入，桟瓦葺で，正面１階は格子，２階は虫籠窓を設け，深い軒を腕木と出桁で受ける。軒高が高く，木割の細い繊細な構えは，明治後期の商家の姿を良く留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002634"},{"id":"00002150","register_sub_id":"101","register_pk":"103140","name":"かぎ楼","kana":"かぎろう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀653","lat":35.22521131,"lng":136.28862793,"geo_status":"db","era":"明治10／大正期増築","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階一部3階建、瓦葺、建築面積308㎡","structure_material":"木造2階一部3階建","registered":"2001.04.24(平成13.04.24)","register_no":"25 － 0144","desc":"かぎ楼は江戸期創業の老舗の料亭旅館である。南北に棟を通す木造２階建，入母屋造の主屋に，３階建の客室棟が接続する。客室棟の内部は数寄屋風にまとめられ，３階の北及び東面に擬宝珠風高欄を廻す。多賀大社門前町のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002150"},{"id":"00009501","register_sub_id":"101","register_pk":"194294","name":"加藤家住宅（旧布惣）一之蔵","kana":"かとうけじゅうたく（きゅうぬのそう）いちのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町1121-1他","lat":35.23671538,"lng":136.25750706,"geo_status":"db","era":"江戸末期／平成21年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0325","desc":"街道に面して主屋の北隣に建つ。土蔵造二階建、桁行五・四メートル梁間五・〇メートル、切妻造瓦葺で、入口を主屋の店舗に面した南面に開く。置屋根とし、扠首組の木鼻に彫刻を施す。主屋と並び建ち、宿場町の歴史的な景観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009501"},{"id":"00009503","register_sub_id":"101","register_pk":"194296","name":"加藤家住宅（旧布惣）三之蔵","kana":"かとうけじゅうたく（きゅうぬのそう）さんのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町1121-1他","lat":35.23659974,"lng":136.25766767,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0327","desc":"敷地背面の東南隅に主屋から離れて建つ。土蔵造二階建、桁行八・一メートル梁間五・一メートル、切妻造瓦葺で、入口を西面に開く。大規模で建ちが高く、軒廻りは桁先をみせず鉢巻を廻す。主屋、一之蔵、二之蔵とともに伝統的な町家の構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009503"},{"id":"00009500","register_sub_id":"101","register_pk":"194293","name":"加藤家住宅（旧布惣）主屋","kana":"かとうけじゅうたく（きゅうぬのそう）しゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町1121-1他","lat":35.23664471,"lng":136.25751919,"geo_status":"db","era":"江戸末期／昭和15年・平成21年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0324","desc":"中仙道高宮宿中心部に建つ元麻布商で街道に西面して建つ。木造二階建、桁行一六・六メートル梁間一二・四メートル、切妻造瓦葺。前面を店舗、背面を田の字型の床上部とする。正面は、海老虹梁状の腕木や二階の幅広の格子窓など当地方の町屋の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009500"},{"id":"00009502","register_sub_id":"101","register_pk":"194295","name":"加藤家住宅（旧布惣）二之蔵","kana":"かとうけじゅうたく（きゅうぬのそう）にのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県彦根市高宮町1121-1他","lat":35.23667683,"lng":136.25761199,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0326","desc":"主屋の背面北側に南面して建つ。土蔵造二階建、桁行三・八メートル梁間四・〇メートル、切妻造瓦葺で、入口を南面に開く。小規模ながら丁寧な造りで、軒廻りは桁先を現した塗籠仕上げとする。主屋、一之蔵、三之蔵とともに伝統的な町家の構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009502"},{"id":"00002640","register_sub_id":"101","register_pk":"103630","name":"かめや旅館広間","kana":"かめやりょかんひろま","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀631","lat":35.224834,"lng":136.288498,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0191","desc":"本館背後に増築された座敷棟。１５畳の主室と１２畳半の次の間からなり，２方に縁を廻らす。主室には床を中心に付書院，花頭窓付き地袋棚を配し，次の間にも地袋棚を備える。良材を用い，造作や建具は丁寧な造りで，座敷飾の独特の構えも巧みにまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002640"},{"id":"00002639","register_sub_id":"101","register_pk":"103629","name":"かめや旅館本館","kana":"かめやりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀631","lat":35.224972,"lng":136.288635,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積155㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0190","desc":"多賀神社門前で江戸時代から営業する料理旅館。通りに面する本館は木造，２階建で，１階は広く土間を取り，２階は中廊下を配して前後に座敷を配する。正面に入母屋造の破風を見せ，その下に切妻造の玄関を張り出した姿は，社頭の景観を構成する主要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002639"},{"id":"00006308","register_sub_id":"101","register_pk":"107291","name":"木之本町きのもと交遊館","kana":"きのもとちょうきのもとこうゆうかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本1118","lat":35.50413345,"lng":136.22594248,"geo_status":"db","era":"昭和10／平成17改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積83㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0246","desc":"湖北銀行木之本支店として建設。北国街道に東面して建つＲＣ造２階建である。旧客溜り部分を保存して背面側を改築した。正面はイオニア式円柱４本の大オーダーを付けた重厚なデザインである。外壁は人造石洗出し仕上げとする。町並みのランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006308"},{"id":"00012956","register_sub_id":"101","register_pk":"368036","name":"旧近江銀行愛知川支店","kana":"きゅうおうみぎんこうえちがわしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県愛知郡愛荘町愛知川38-2","lat":35.17180278,"lng":136.20772778,"geo_status":"db","era":"大正15年頃／平成30年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積161㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 439","desc":"旧愛知川宿中心部にある旧銀行店舗。鉄筋コンクリート造平屋建の一部2階建。正面中央部を枠取って西洋古典様式基調の意匠で整え、パラペット中央に幾何学的な意匠の軒飾を付す。県下における最初期の鉄筋コンクリート造建築で、地域の近代化を象徴する存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012956"},{"id":"00016399","register_sub_id":"101","register_pk":"536466","name":"旧小澤家住宅店舗兼主屋","kana":"きゅうおざわけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀627","lat":35.22474444,"lng":136.28917222,"geo_status":"db","era":"江戸末期／平成28年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"25 - 0530","desc":"多賀大社の門前町に位置し、かつて土産物屋を営んだ商家の主屋。多賀道に北面する二階建切妻造平入桟瓦葺で正面に下屋を付す。二階外壁は漆喰塗仕上で両端に袖壁を付す。一階東は旧の土間、西は床上で南西に角座敷を附属。通りに面し門前の景観をつくる町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016399"},{"id":"00016401","register_sub_id":"101","register_pk":"536468","name":"旧小澤家住宅土蔵","kana":"きゅうおざわけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀627","lat":35.22478611,"lng":136.28911111,"geo_status":"db","era":"江戸末期／平成28年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積20㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"25 - 0532","desc":"主屋の西側に位置する土蔵。2階建切妻造桟瓦葺の東西棟で北面に庇を付す。外壁漆喰塗仕上で東面に戸口を開け、北面に窓を二箇所開ける。絵様付腕木で軒桁を支持するなど軒廻り賑やかで、小規模ながらも主屋と一体となって門前の歴史的な景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016401"},{"id":"00016400","register_sub_id":"101","register_pk":"536467","name":"旧小澤家住宅離れ","kana":"きゅうおざわけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"滋賀県","address":"滋賀県犬上郡多賀町大字多賀627","lat":35.224675,"lng":136.28911111,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"25 - 0531","desc":"主屋の南に接続する離れ座敷。平屋建切妻造桟瓦葺の南北棟で北・西に銅板葺下屋を付す。内部は２室の続き間座敷で南室東面に床を構え、各室は西面の広縁や濡縁を介して庭を望む。床柱に竹を用い、書院障子の組子や欄間彫刻など要所に繊細な意匠を用いる離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016400"},{"id":"00013739","register_sub_id":"101","register_pk":"505285","name":"旧木之本宿本陣（竹内家住宅）主屋","kana":"きゅうきのもとしゅくほんじん（たけうちけじゅうたく）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町941-1","lat":35.50531111,"lng":136.22567222,"geo_status":"db","era":"延享元年(1744)／平成30年改修","year":1744,"year_source":"db","year_min":1744,"year_max":1744,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積249㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 470","desc":"北国街道に西面する間口六間半の大規模町家。つし二階建切妻造平入桟瓦葺で、南を通り土間、北の表を一室の広いミセとし、その奥に二列六室を配する。たちが低く古式で、平面や小屋組に当初形式をよく残す。一八世紀前半に遡る木之本宿の本陣遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013739"},{"id":"00010477","register_sub_id":"101","register_pk":"199431","name":"旧滋賀銀行甲南支店","kana":"きゅうしがぎんこうこうなんしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲南町寺庄字上川原1078","lat":34.917886,"lng":136.181947,"geo_status":"db","era":"大正14／昭和50改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積150㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"25 － 0357","desc":"寺庄集落中ほどで杣街道に面して建つ。鉄筋コンクリート造で正面に矩形の柱形を張出し、内側にイオニア式オーダーを表し重厚なエンタブレチュアを支える。玄関上部は半円アーチの窓を設け装飾的な持送りを兼ねた要石を飾り、銀行建築らしい古典的意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010477"},{"id":"00000059","register_sub_id":"101","register_pk":"101049","name":"黒壁ガラス館本館（旧第百三十銀行長浜支店）","kana":"くろかべがらすかんほんかん（きゅうだいひゃくさんじゅうぎんこうながはましてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市元浜町12-38","lat":35.38069376,"lng":136.26709716,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積169㎡","structure_material":"木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"25 － 0001","desc":"伝統的な土蔵造を基調として，軒蛇腹，上下窓，天井飾等の要所に洋風の意匠を取り入れた建物。明治期には多くの銀行が土蔵造でつくられたが，滋賀県下における初期の事例のひとつである。黒漆喰塗りの外観から｢黒壁｣の愛称を持ち，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000059"},{"id":"00009498","register_sub_id":"101","register_pk":"194291","name":"阪本屋店舗兼主屋","kana":"さかもとやてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市長等1-240他","lat":35.00810318,"lng":135.86102479,"geo_status":"db","era":"昭和11年／昭和中期改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積239㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0322","desc":"通りに北面する二階建町家。切妻造桟瓦葺で、正面に下屋を設ける。正面は、下階東側を店舗とし、西側は腰を御影石張とする。上階は黒色の小口タイル貼として中央に看板用の小屋根を突出す。内部では洋風の応接間を設けるほか、細部意匠にも趣向を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009498"},{"id":"00009036","register_sub_id":"101","register_pk":"162396","name":"滋賀中央信用金庫銀座支店店舗","kana":"しがちゅうおうしんようきんこぎんざしてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県彦根市河原3-117","lat":35.26617105,"lng":136.2550518,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、スレート葺、建築面積54㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0304","desc":"市街地の交差点に建ち、木造二階建、建築面積５４㎡、寄棟造スレート葺である。交差点側を隅切りして腰折れ破風を載せ、左右に切妻破風を並べる。外壁は二階分の柱形と縦長窓を配するなど、瀟洒な外観で街角のアイストップとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009036"},{"id":"00002047","register_sub_id":"101","register_pk":"103037","name":"竹平楼御在所","kana":"たけへいろうございしょ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県愛知郡愛荘町愛知川1608","lat":35.169476,"lng":136.206879,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"25 － 0139","desc":"竹平楼は中山道沿いに位置する江戸後期創業の旅籠で，明治１１年の明治天皇御巡幸に際して新築。南北棟，入母屋造，妻入で，各１間幅の床・床脇・付書院をもつ８畳を主室とし，半間幅の縁が南西２面に取付く。材料・意匠とも質の高い数寄屋風書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002047"},{"id":"00002048","register_sub_id":"101","register_pk":"103038","name":"竹平楼広間","kana":"たけへいろうひろま","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県愛知郡愛荘町愛知川1608","lat":35.169521,"lng":136.206711,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"25 － 0140","desc":"敷地のほぼ中央に位置する東西棟，入母屋造，桟瓦葺の平屋建で，１０畳６室を３室２列に配置し，南北の両平側に半間幅の疎垂木木舞裏天井の縁廊下を付ける。各列端部に床・棚を設えた書院風広間になり，大工棟梁は湖東町今在家の木沢助次郎とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002048"},{"id":"00001195","register_sub_id":"101","register_pk":"102185","name":"中村商家保存館主屋","kana":"なかむらしょうかほぞんかんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市旭町5","lat":35.27407349,"lng":136.261246,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造２階建，瓦葺，建築面積216㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"25 － 0112","desc":"彦根城下の東部地区を南北に通る町屋街の角地に東面して建つもと酒小売店舗。間口約１４ｍ、奥行約１２ｍの規模で、表側南半分を土間、北半分を田字型８畳４室とし、つし２階を設ける伝統的形式をとる。彦根における町屋の変遷を知るうえで貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001195"},{"id":"00007056","register_sub_id":"101","register_pk":"108038","name":"双葉館魚寅楼奥座敷","kana":"ふたばかんうおとらろうおくざしき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県草津市草津二丁目字下御田伝532他","lat":35.015926,"lng":135.961243,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積114㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"25 － 0256","desc":"本館の東側に接続し、庭園に面して建つ。建築面積１１４㎡、木造２階建、入母屋造及び切妻造瓦葺で、１、２階とも庭園側に縁と庇を巡らす。全体に良材を用いて丁寧に仕上げており、１階の大広間は折上格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007056"},{"id":"00007057","register_sub_id":"101","register_pk":"108039","name":"双葉館魚寅楼塀","kana":"ふたばかんうおとらろうへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県草津市草津二丁目字下御田伝532他","lat":35.01604224,"lng":135.96114054,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、瓦葺、延長11m","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"25 － 0257","desc":"本館の旧玄関から道路沿いに延びる。折曲り延長１１ｍ、木造、瓦葺。延石上に節丸太の柱を建てて地覆をまわし、瓦には目板瓦を用いる。本館同様、腰を竪板張、内法壁は赤色とし、隅切矩形の窓を開ける。料亭の外塀に相応しい、瀟洒で上品な塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007057"},{"id":"00007055","register_sub_id":"101","register_pk":"108037","name":"双葉館魚寅楼本館","kana":"ふたばかんうおとらろうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県草津市草津二丁目字下御田伝532他","lat":35.015987,"lng":135.961029,"geo_status":"db","era":"昭和11頃／昭和63改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積243㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"25 － 0255","desc":"角地に建つ料亭建築で、２階に８０畳敷の大広間をもつ。建築面積２４３㎡、木造２階建、入母屋造桟瓦葺。通りに面する北側は、腰を竪板張、内法壁を赤色とし、料亭らしく仕上げる。南側は庭園に面し、２階に高欄付の縁をまわすなど、開放的なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007055"},{"id":"00006571","register_sub_id":"101","register_pk":"107554","name":"古川家住宅主屋","kana":"ふるかわけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県犬上郡豊郷町四十九院919","lat":35.207333,"lng":136.234329,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積142㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0242","desc":"旧中山道に東面する敷地の北東寄りに建つ。油商の店舗兼住宅として建設。間口６間半，奥行６間半の妻入で，茅葺屋根を瓦形鉄板仮葺とする。元は南側に通り土間，床上部に２列６室型の居室を設け，表側を土間とする。街路から塀越しに見える入母屋屋根が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006571"},{"id":"00000297","register_sub_id":"101","register_pk":"101287","name":"本家鶴喜そば主屋","kana":"ほんけつるきそばしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本4-11-40","lat":35.07059813,"lng":135.87026601,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建，瓦葺，建築面積167㎡","structure_material":"木造2階建","registered":"1997.09.03(平成9.09.03)","register_no":"25 － 0007","desc":"木造２階建，入母屋造，桟瓦葺の平入り町家である。２階の高欄や屋根の正面に取りつけた向拝風の屋根，千鳥破風の妻飾等に外観の特色がある。江戸時代中頃から続くそば屋の店舗として，坂本の町並みの入口にあって広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000297"},{"id":"00009032","register_sub_id":"101","register_pk":"162392","name":"豆信蔵","kana":"まめしんくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市長等3-308","lat":35.01115747,"lng":135.85938233,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0300","desc":"主屋後方に中庭を介して南北棟で建つ。桁行８．４ｍ梁間４．０ｍ、木造二階建、入母屋造妻入、桟瓦葺で、北妻を出入口として庇を付ける。外部は漆喰塗で、内部は一階を土間とし、二階は居室として西面に窓を開ける。料亭の附属建物の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009032"},{"id":"00009033","register_sub_id":"101","register_pk":"162393","name":"豆信門塀","kana":"まめしんもんへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市長等3-308","lat":35.01141513,"lng":135.85936002,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、瓦葺、総延長8.2m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0301","desc":"主屋玄関正面に構えた門を含み、敷地東南面に折曲がりに塀を廻らす。門は格子戸引分けとし、桟瓦葺の庇を葺下ろす。塀は、延長８．２ｍ、両下造桟瓦葺で、腰に高く竪板を張り、上部を漆喰塗りとする。主屋と調和が図られた外観が料亭らしい情緒を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009033"},{"id":"00009031","register_sub_id":"101","register_pk":"162391","name":"豆信料亭棟","kana":"まめしんりょうていとう","category":"産業3次","subcategory":"建築物","type_guess":"料亭","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市長等3-308","lat":35.01135958,"lng":135.85929071,"geo_status":"db","era":"大正7年／昭和9年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"25 － 0299","desc":"大津旧市街地の角地に建ち、木造二階建、建築面積１７０㎡、入母屋造桟瓦葺である。一階正面は格子を建て、大広間のある二階の窓には高欄風の手摺を付けるほか、大小の格子窓を配して瀟洒な外観とする。往時の賑わいを伝える料亭建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009031"},{"id":"00000217","register_sub_id":"101","register_pk":"101207","name":"丸八百貨店","kana":"まるはちひゃっかてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県高島市朽木市場838・847","lat":35.35410302,"lng":135.91605615,"geo_status":"db","era":"昭和8頃／昭和18頃増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造3階建，スレート葺，建築面積83㎡","structure_material":"木造3階建","registered":"1997.06.12(平成9.06.12)","register_no":"25 － 0003","desc":"村の中心部の角地に建つ百貨店。もとは２階建で、３階は物見櫓等に利用するために増築された。人造石洗い出しの外壁の２階と３階の間の帯状に廻らされた鋸歯形の模様（当初のパラペット飾り）等に特徴があり、村でひときわ目をひく建物としてよく知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000217"},{"id":"00006153","register_sub_id":"101","register_pk":"107137","name":"八百久店舗兼主屋","kana":"やおきゅうてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県草津市草津3-11-37","lat":35.014664,"lng":135.958054,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"25 － 0239","desc":"市中心部を貫く旧東海道に西面して建つ。桁行４間，梁間６間半，切妻造，平入で，正面を出桁造とする町家建築。棟通りをやや後退させて，２階の空間を確保しつつ，正面で軒高を抑え，格子窓や木瓜形虫籠窓を配するなど，町並みとの調和を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006153"},{"id":"00006145","register_sub_id":"101","register_pk":"107129","name":"吉川芳樹園店舗兼主屋","kana":"よしかわほうじゅてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県草津市草津2-7-33","lat":35.017372,"lng":135.960358,"geo_status":"db","era":"江戸末期／昭和50頃改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部3階建、瓦葺、建築面積158㎡","structure_material":"木造平屋一部3階建","registered":"2007.05.15(平成19.05.15)","register_no":"25 － 0238","desc":"市中心部を貫く旧東海道に西面して建つ。桁行５間半，梁間６間半規模で，平入とし，街路に面する南北棟切妻造の背面で棟が直交するＴ字形の屋根形式をもつ。正面に虫籠窓の意匠を残し，出桁等を漆喰で塗り込める。旧草津宿の歴史的景観を構成する町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006145"},{"id":"00000256","register_sub_id":"101","register_pk":"101246","name":"新井ビル","kana":"あらいびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区今橋2-1-1","lat":34.6907452,"lng":135.50638848,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建，建築面積254㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"1997.07.15(平成9.07.15)","register_no":"27 － 0021","desc":"鉄筋コンクリート４階建、１階正面の玄関部分は４本のドリス式オーダーを並べた重厚な外観になる。もと銀行店舗として建設されたもので、内部は中央が吹き抜けとなり２階周囲に個室を稗史階以上は事務室とする構成になる。設計河合浩蔵、施工清水組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000256"},{"id":"00016681","register_sub_id":"101","register_pk":"579165","name":"淡路町洋館（旧中井歯科商店）","kana":"あわじまちようかん（きゅうなかいしかしょうてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区淡路町三丁目48","lat":34.686849,"lng":135.501595,"geo_status":"db","era":"大正後期／昭和16年・令和7年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"鉄筋コンクリート造3階建、建築面積59㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2026.07.09(令和8.07.09)","register_no":"27 - 0972","desc":"淡路町の交差点に建つ旧歯科用品卸商の店舗。鉄筋コンクリート造3階建、外壁スクラッチタイル貼。額縁状に縁取った北東隅部は柱形を現し、一階を石張風、上階をクリーム色モルタル塗仕上とした対照的なつくりとする。角地を強調する独特な外観の事務所ビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016681"},{"id":"00004148","register_sub_id":"101","register_pk":"105138","name":"いけだピアまるセンター（旧池田実業銀行本店）","kana":"いけだぴあまるせんたー（きゅういけだじつぎょうぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府池田市新町2-14","lat":34.82716927,"lng":135.42400248,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積303㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0291","desc":"鉄筋コンクリート造２階建で，外部は基底部を石張風に仕上げ，隅部及び１，２階縦長上げ下げ窓間の狭い壁面を褐色タイル張とし，頂部をアーキトレイブ風につくる。銀行建築らしい重厚さと近代的感覚を合わせ持つ。設計は鉄道院出身で大阪で活躍した小笠原鈅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004148"},{"id":"00000222","register_sub_id":"101","register_pk":"101212","name":"生駒時計店","kana":"いこまとけいてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区平野町2-2-12","lat":34.687532,"lng":135.50635577,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造地上5階地下1階建塔屋付，建築面積176㎡","structure_material":"鉄筋コンクリート造地上5階地下1階建塔屋付","registered":"1997.06.12(平成9.06.12)","register_no":"27 － 0019","desc":"大阪市街地の角地に建つRC造、５階建の時計塔を持つビルで、設計は宗兵蔵である。外壁にスクラッチタイルを用いることや、窓の上下の縁で水平線を強調しつつバルコニーや出窓などに曲線や装飾を有効に配するデザインによく時代の特徴があわらわている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000222"},{"id":"00014870","register_sub_id":"101","register_pk":"519130","name":"立売堀ビルディング","kana":"いたちぼりびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区立売堀一丁目24-1他","lat":34.680025,"lng":135.49668889,"geo_status":"db","era":"昭和3年／昭和中期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積128㎡、塔屋付","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0897","desc":"四つ橋筋に東面するオフィスビル。鉄筋コンクリート造地上4階地下1階建で、外観は三層構成で柱形が垂直性を高め、柱頭にセセッション風レリーフを配す。内部は店舗を配す１階以外を中廊下式平面とする。大正後期に拡幅した四つ橋筋の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014870"},{"id":"00003566","register_sub_id":"101","register_pk":"104556","name":"稲束家住宅主屋","kana":"いなつかけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府池田市綾羽1-2466","lat":34.82675745,"lng":135.42602831,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積254㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"27 － 0259","desc":"近世の在郷町中心地を南北に通る街路に東面して建つ。間口５間半規模の切妻造，本瓦葺の平入つし２階建商家で，南方を下手とし，土間奥に角屋を出し，北西方に座敷棟を張り出す。正面はつし２階に大きな虫籠窓を開け，庇と２階壁面を北に延ばして表門をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003566"},{"id":"00001630","register_sub_id":"101","register_pk":"102620","name":"宇野薬局","kana":"うのやっきょく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区徳井町2-3-3","lat":34.68411204,"lng":135.51189162,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造3階建、瓦葺、建築面積58㎡","structure_material":"木造3階建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0091","desc":"松屋町筋の角地に西面して建つ。木造３階建，タイル張の看板建築で，各階軒の水平線，３階側面の丸窓，パラペットに載せた緑色のスパニッシュ風瓦などに昭和初期の意匠傾向が認められる。設計は坂本建築事務所，施工は西成の長岡栄吉と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001630"},{"id":"00014054","register_sub_id":"101","register_pk":"508314","name":"大阪農林会館ビル","kana":"おうさかのうりんかいかんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区南船場三丁目15-10他","lat":34.67689722,"lng":135.50310833,"geo_status":"db","era":"昭和5年／同24年以降改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造5階地下1階建、建築面積770㎡、塔屋付","structure_material":"鉄筋コンクリート造5階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0830","desc":"南船場中心部の交差点に建つテナントビル。鉄筋コンクリート造地上五階地下一階建、外壁は一階石張、二階以上タイル張。南西隅に旧正面玄関、北東に玄関を設ける。内部は階段室やメールシュート、金庫室等に往時の意匠を見る。改変少なく地域景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014054"},{"id":"00003270","register_sub_id":"101","register_pk":"104260","name":"大阪ガスビルディング","kana":"おおさかがすびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区平野町4-1、4-2-1、4-3-1","lat":34.68795,"lng":135.500061,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上8階地下2階建、建築面積2253㎡","structure_material":"鉄骨鉄筋コンクリート造地上8階地下2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0215","desc":"御堂筋に面して建つ本社社屋。設計は安井武雄，施工は大林組。ＳＲＣ造，地上８階地下２階建で，外壁は１・２階を石材で黒くまとめ，上部は白色のタイル張。水平垂直の要素を取り混ぜた外観や内部にも質の高い意匠を持つ，過渡期的近代建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003270"},{"id":"00014871","register_sub_id":"101","register_pk":"519131","name":"大阪ガスビルディング北館","kana":"おおさかがすびるでぃんぐきたかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和後","pref":"大阪府","address":"大阪府大阪市中央区道修町四丁目29-1他","lat":34.68823889,"lng":135.50020278,"geo_status":"db","era":"昭和41年／平成18年改修","year":1966,"year_source":"db","year_min":1966,"year_max":1966,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上8階地下3階建、建築面積2，348㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造地上8階地下3階建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0898","desc":"御堂筋に面し、安井武雄設計の南館の北に建つ増築棟。鉄骨鉄筋コンクリート造地上8階地下3階建で、大胆に変更した柱割が新旧の区別と全体の調和を生み、各階庇の連続や同種外装材を用いて端正な南館の意匠を継承する。御堂筋の象徴的なオフィスビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014871"},{"id":"00003285","register_sub_id":"101","register_pk":"104275","name":"岡本家住宅主屋","kana":"おかもとけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-11","lat":34.450294,"lng":135.357727,"geo_status":"db","era":"江戸中期／天保12増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積228㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0230","desc":"岡本家はト半役所西面の御下筋北端東側で醤油醸造業を営んだ有力町人。主屋は間口６間の平入り町家で，利齋家と同様綴葺の屋根を持つ。増築の角屋座敷に天保１２年の棟札があり，本体は１８世紀中期頃まで上ると見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003285"},{"id":"00007512","register_sub_id":"101","register_pk":"108494","name":"小川香料大阪支店社屋","kana":"おがわこうりょうおおさかしてんしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区平野町2-3-1他","lat":34.687836,"lng":135.50441,"geo_status":"db","era":"昭和5／昭和38増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造3階地下1階建、建築面積153㎡","structure_material":"鉄筋コンクリート造一部鉄骨造3階地下1階建","registered":"2009.01.08(平成21.01.08)","register_no":"27 － 0521","desc":"三休橋筋東側の街区に南面して建つ。建築面積１５３㎡、鉄筋コンクリート造、地上４階、地下１階建。円弧を用いた窓枠と窓庇を交差させた独特な意匠をみせ、玄関上部には八角形のステンドグラスをあしらうなど、全体をアールデコ様式でまとめた佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007512"},{"id":"00004145","register_sub_id":"101","register_pk":"105135","name":"奥山家住宅主屋","kana":"おくやまけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西淀川区姫島1-13-1、2","lat":34.702351,"lng":135.456558,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"27 － 0288","desc":"燃料店を営んだ家の店舗兼住居で，表通りに南面して建つ。東から住居，店舗，倉庫を並べ，東端住居部分は２階建とする。各部で高さを変えたパラペットを立ち上げ陸屋根風に見せ，外壁はスクラッチタイル張とし，庇もコーニス状に造るなど洋風意匠に腐心する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004145"},{"id":"00014059","register_sub_id":"101","register_pk":"508319","name":"小野家住宅店舗兼主屋","kana":"おのけじゅうたくてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府枚方市新町一丁目5-1","lat":34.81857222,"lng":135.649475,"geo_status":"db","era":"江戸末期／昭和前期・同41年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積206㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0835","desc":"枚方宿の旧京街道に西面する大規模町家。江戸時代は醤油屋を営み庄屋を務めた。切妻造桟瓦葺平入つし二階建、通り土間の北に二列六室、南に一列三室を配す。外観は揚見世や半蔀等の設備がよく残り、内部の座敷も改変が少ない。旧街道の景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014059"},{"id":"00014061","register_sub_id":"101","register_pk":"508321","name":"小野家住宅道具蔵","kana":"おのけじゅうたくどうぐぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府枚方市新町一丁目5-1","lat":34.8185,"lng":135.64958333,"geo_status":"db","era":"江戸末期／昭和35年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0837","desc":"主屋背面側の敷地南辺中央に建つ土蔵。切妻造桟瓦葺、北面に下屋庇を設ける。基礎は花崗岩切石、外壁は漆喰仕上で軒裏を波型に塗り込める。各階もとは一室だが、一階は階段室と区画して洋室に改修し、開口にガラス戸が建つ。二階は改変なく登り梁を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014061"},{"id":"00014060","register_sub_id":"101","register_pk":"508320","name":"小野家住宅離れ","kana":"おのけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府枚方市新町一丁目5-1","lat":34.81853611,"lng":135.64961111,"geo_status":"db","era":"江戸末期／平成25年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0836","desc":"主屋の東背面に中庭を挟んで建つ離れ。木造平屋建、中庭側の西面切妻造庇付、背面側入母屋造で桟瓦葺。内部は床を備えた八畳間一室だが現在は洋室とする。中庭側に廊下を通し、渡廊下で主屋と繋がる。主屋及び中庭と一体になって敷地内の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014060"},{"id":"00003290","register_sub_id":"101","register_pk":"104280","name":"尾食家住宅主屋","kana":"おめしけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町38-19","lat":34.451691,"lng":135.358414,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造2階建、瓦葺、建築面積290㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0235","desc":"貝塚寺内町北側の入口に当たる上方口の西側に建つ。川沿いにあるためもともと台形平面で，町外からの見付となる北側は段違いに破風を構えた入母屋造とし，且つ昭和１６年の道路拡幅で前面南側を３角に切り取られているため複雑な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003290"},{"id":"00006185","register_sub_id":"101","register_pk":"107169","name":"貝塚市歴史展示館（旧ユニチカ株式会社貝塚工場事務所）","kana":"かいづかしれきしてんじかん（きゅうゆにちかかぶしきがいしゃかいづかこうじょうじむしょ）","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市半田138-1","lat":34.44186,"lng":135.370041,"geo_status":"db","era":"昭和10／昭和20増築・平成17改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積326㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0419","desc":"ＪＲ東貝塚駅の北方に広がる旧ユニチカの敷地に南面して建つ。Ｌ字形平面，正面１９ｍの旧事務所部分の東側に，玄関ポーチ付建屋を増築したもので，全体に寄棟屋根を載せ，窓上下に水平材を廻らすことで外観を整える。紡績業で繁栄した近代大阪の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006185"},{"id":"00014639","register_sub_id":"101","register_pk":"515181","name":"鍵屋別棟","kana":"かぎやべつむね","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府枚方市堤町215他","lat":34.81196389,"lng":135.63703333,"geo_status":"db","era":"昭和3年／昭和8年頃増築、平成13年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積293㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0883","desc":"枚方宿に所在する料理旅館の別棟。東棟に玄関と二階客室、西棟に客室と二階大広間を持ち、廊下や階段で繋ぐ。地階には淀川からの船入石垣を残す。大広間はキングポスト・トラス小屋組で大空間を実現した折上格天井床構え付六三畳間で縁高欄越しに淀川を望む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014639"},{"id":"00001929","register_sub_id":"101","register_pk":"102919","name":"片桐棲龍堂西ノ蔵","kana":"かたぎりせいりゅうどうにしのくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区西湊町3-1-16","lat":34.56754469,"lng":135.4640619,"geo_status":"db","era":"江戸後期／明治6移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0110","desc":"大阪市街日本橋から明治６年に移築された土蔵で，主屋の西方，アプローチ通路を隔てた位置に建つ。桁行３間，梁行４間，東西棟，切妻造，本瓦葺，妻入の比較的規模の大きな２階建土蔵で，現在は漢方資料館として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001929"},{"id":"00006699","register_sub_id":"101","register_pk":"107682","name":"交野市立教育文化会館（旧交野無尽金融株式会社本社屋）","kana":"かたのしりつきょういくぶんかかいかん（きゅうかたのむじんきんゆうかぶしきがいしゃほんしゃおく）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府交野市倉治6-9-21","lat":34.79632055,"lng":135.68990298,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積282㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0447","desc":"正面１９ｍ奥行１５ｍ規模、鉄筋コンクリート造２階建、スクラッチタイル貼の銀行建築で、大林組の設計施工になる。銀行建築には珍しくゴシック系のデザインを採り、営業室まわりにチューダーアーチを配し、パラペットに中世城郭風の狭間を廻らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006699"},{"id":"00016413","register_sub_id":"101","register_pk":"536480","name":"紙野家住宅主屋","kana":"かみのけじゅうたくおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府貝塚市近木町1065-13","lat":34.44689167,"lng":135.35631944,"geo_status":"db","era":"昭和26年／平成5年頃改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積109㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"27 - 0952","desc":"南海貝塚駅の北西に位置し、通りに東面する旧遊郭。二階建切妻造桟瓦葺で正面中央の玄関に出節柱を立て、二階窓の腰に格狭間を飾る。玄関はタイル敷の土間で船底天井とし、北面に勘定台を備える。二階は六室の座敷を配し、細部まで凝ったつくりの遊郭建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016413"},{"id":"00003684","register_sub_id":"101","register_pk":"104674","name":"河村商店（旧加島銀行池田支店）","kana":"かわむらしょうてん（きゅうかしまぎんこういけだしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府池田市栄本町3172-1","lat":34.8256989,"lng":135.42540714,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積330㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"27 － 0270","desc":"池田市の中心街にあって，能勢街道に面して建つ。設計は辰野片岡建築事務所。木造２階建であるが，石と赤煉瓦の外観で組積造風に見せる。窓上や柱型上部にやや抽象化された装飾を設け，正面西側部分はマンサード屋根の破風を設け，塔屋風に見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003684"},{"id":"00010006","register_sub_id":"101","register_pk":"196153","name":"川本家住宅倉庫","kana":"かわもとけじゅうたくそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府茨木市上泉町1167","lat":34.82326752,"lng":135.57183102,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0582","desc":"店舗兼主屋の西奥に南北棟で建つ。木造平屋建、桁行八・〇メートル梁間五・〇メートル、切妻造鉄板葺である。外壁は軒下まで杉皮張とし、小屋は和小屋を組む。東西面に出入口を設け、店舗兼主屋からのトロッコレールを引き込む。商家の生業の様態を伝える倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010006"},{"id":"00010004","register_sub_id":"101","register_pk":"196151","name":"川本家住宅店舗兼主屋","kana":"かわもとけじゅうたくてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府茨木市上泉町1167","lat":34.82327692,"lng":135.5720479,"geo_status":"db","era":"昭和3／平成17改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積182㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0580","desc":"通りに東面する間口六間の町家で、二階正面を黒漆喰塗とし両端に袖壁を設ける。一階内部は前面を広いミセとして背面北寄りに座敷を配し、南寄りの通り土間に敷地奥の倉庫にのびるトロッコレールを残す。近世以来商工業の拠点として栄えた茨木の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010004"},{"id":"00010005","register_sub_id":"101","register_pk":"196152","name":"川本家住宅離れ","kana":"かわもとけじゅうたくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府茨木市上泉町1167","lat":34.82334408,"lng":135.57189859,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡、渡廊下付","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"27 － 0581","desc":"店舗兼主屋の後方に渡廊下を介して建つ。屋根はやや起りのある入母屋造で桟瓦葺とし、東西に八畳と六畳を並べて縁を廻らせる。八畳はトコの左右に違棚と琵琶棚を配し、幅広の付書院を設ける。六畳もトコ棚を備え、いずれも銘木などを多用し趣向を凝らせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010005"},{"id":"00000417","register_sub_id":"101","register_pk":"101407","name":"北浜レトロビルヂング（旧桂隆産業ビル）","kana":"きたはまれとろびるち゛んぐ（きゅうけいりゅうさんぎょうびる）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区北浜1-1-26","lat":34.69172372,"lng":135.50749623,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"煉瓦造地上2階地下1階建，建築面積56㎡","structure_material":"煉瓦造地上2階地下1階建","registered":"1997.12.12(平成9.12.12)","register_no":"27 － 0029","desc":"土佐堀通りに面して建つ小規模な煉瓦造建築。正面開口部は，花崗岩の切石を用いて縁取りし，玄関廻りを変形アーチを４本の柱型で受け，２階は大きく開く窓枠を置いてアクセントとする。近隣の洋風建築とも，金融の町北浜の往事の面影を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000417"},{"id":"00006009","register_sub_id":"101","register_pk":"106994","name":"ギャラリー再会","kana":"ぎゃらりーさいかい","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市浪速区恵美須東1-4-16","lat":34.65273757,"lng":135.50686138,"geo_status":"db","era":"昭和28／平成9改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、スレート葺、建築面積97㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"27 － 0414","desc":"通天閣から放射状にのびる街路沿いに建つ。間口３間，奥行１０間で，中庭を介して店舗と住居を通路で繋ぐ伝統的町家形式を踏襲したつくり。独特の幾何学模様の破風飾り，ねじれ柱付のバルコニー，ガス灯風の照明など，舞台美術を思わせるファサードが特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006009"},{"id":"00005287","register_sub_id":"101","register_pk":"106275","name":"旧和泉銀行本店（Ｃ．Ｔ．Ｌ．ＢＡＮＫ）","kana":"きゅういずみぎんこうほんてん（しー・てぃー・える・ばんく）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府岸和田市北町14-3","lat":34.464527,"lng":135.373062,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積328㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0341","desc":"鉄筋コンクリート造２階建の銀行建築。外壁はタイル張で，隅部を石積風につくり，腰とコーニスにはテラコッタを張る。正面中央入口は２階分の半円アーチ窓を設け，キーストーンの位置にメダリオンを飾る。紀州街道に面して建ち，地域景観のシンボル的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005287"},{"id":"00013423","register_sub_id":"101","register_pk":"368508","name":"旧十八屋（櫻館）主屋","kana":"きゅうじゅうはちや（さくらかん）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区桜之町西三丁4","lat":34.58981111,"lng":135.481125,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"27 － 0801","desc":"短冊形の敷地で、通りに西面して建つ。つし二階建の二軒長屋で、規模の異なる北棟と南棟からなる。共に南にトオリニワを配し、北に北棟は一列三室、南棟は一列二室の座敷を並べる。連続する一階の格子状の駒寄、二階の虫籠窓など、近世町家の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013423"},{"id":"00012580","register_sub_id":"101","register_pk":"367875","name":"旧丹治商会社屋","kana":"きゅうたんじしょうかいしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府堺市堺区永代町一丁7-1","lat":34.569778,"lng":135.473083,"geo_status":"geocoded","era":"明治後期／平成29年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、銅板葺、建築面積58㎡","structure_material":"煉瓦造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0753","desc":"市中心部の住宅地の一角に南面して建つ、もと煉瓦製造会社の社屋。煉瓦造二階建、外壁化粧煉瓦張で、四隅に柱形を表し、欠円アーチの縦長窓を並べ、アーチに沿って水切二段を設ける。コーニスに持送と歯飾を付し、背面に円窓を穿つなど瀟洒な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012580"},{"id":"00012581","register_sub_id":"101","register_pk":"367876","name":"旧丹治商会門及び煉瓦塀","kana":"きゅうたんじしょうかいれんがべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府堺市堺区永代町一丁7-1","lat":34.569778,"lng":135.473083,"geo_status":"geocoded","era":"明治後期／平成29年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 石造、間口2.1m 煉瓦塀 煉瓦造、総延長18m","structure_material":"門 石造","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0754","desc":"社屋入口正面に立つ石製門とその左右に延び前庭を区切る煉瓦塀。煉瓦塀の正面は煉瓦を千鳥に積んだ透塀で、要所を焼過煉瓦や役物で飾る。両側面は高さ４メートルの高塀で、外観を社屋と調和させる。煉瓦製造を営んだ会社らしく意匠性と堅牢性を兼ね備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012581"},{"id":"00014188","register_sub_id":"101","register_pk":"508818","name":"鴻池組旧本店洋館","kana":"こうのいけぐみきゅうほんてんようかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市此花区伝法四丁目63-1","lat":34.688725,"lng":135.45456667,"geo_status":"db","era":"明治43年／大正3年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、スレート葺、建築面積90㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0838","desc":"此花区伝法に北面する洋館。二階建寄棟造平入スレート葺で東に和館が接続。頂部の櫛形ペディメントに社章を掲げ、外壁はモルタル仕上に煉瓦タイル貼ボーダーを巡らす。内部二階応接室の内装は濃密なアール・ヌーヴォー意匠とし、時代の息吹を伝える洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014188"},{"id":"00014189","register_sub_id":"101","register_pk":"508819","name":"鴻池組旧本店和館","kana":"こうのいけぐみきゅうほんてんわかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市此花区伝法四丁目63-1","lat":34.688725,"lng":135.45468333,"geo_status":"db","era":"明治43年／昭和前期増築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積154㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"27-0839","desc":"洋館東隣に建つ二階建切妻造平入桟瓦葺の和館。外観は重厚な町家で、両端に袖壁を立上げ、軒は出桁で持出し、垂木形に塗込める。内部は東を土間とした二列五室で、南庭に張出す二階座敷は意匠を凝らした数寄屋造。重厚な外観ながら繊細な内部意匠の和館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014189"},{"id":"00015205","register_sub_id":"101","register_pk":"530629","name":"後藤家住宅三階蔵","kana":"ごとうけじゅうたくさんがいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区大手通一丁目4","lat":34.68621389,"lng":135.51656389,"geo_status":"db","era":"明治44年／昭和32年移築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積33㎡","structure_material":"土蔵造3階建","registered":"2024.12.03(令和6.12.03)","register_no":"27 - 0938","desc":"大阪谷町筋で洋服製造販売及び卸売を営んだ商家の商品蔵兼家財蔵。寄棟造桟瓦葺、建ちの低い三階建の土蔵で外壁は白漆喰塗仕上、腰を竪板張とする。南面戸口に両開き土戸を吊り、各階窓に漆喰塗込の庇を付す。大阪の服飾業の発展を伝える貴重な三階建土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015205"},{"id":"00006291","register_sub_id":"101","register_pk":"107274","name":"小林新聞舗店舗兼住宅","kana":"こばやししんぶんほてんぽけんじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市平野区平野本町4-12-3","lat":34.6236,"lng":135.555084,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階建及び木造平屋建、瓦葺、建築面積142㎡","structure_material":"鉄筋コンクリート造2階建及び木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"27 － 0423","desc":"商店街のアーケードに北面して建つ。ＲＣ造２階建の店舗の背後に木造平屋建の住居が接続する。正面中央西寄りに店舗入口，東端に住居の通り土間への戸口を開き，小庇を付ける。正面は柱形で４分割し，２階に２つずつ配したアーチ形の窓枠が外観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006291"},{"id":"00004381","register_sub_id":"101","register_pk":"105371","name":"西條合資会社旧店舗主屋","kana":"さいじょうごうしがいしゃきゅうてんぽしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市長野町13-11","lat":34.44926514,"lng":135.57043587,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積286㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0309","desc":"街路に北面して建つ造り酒屋。桁行１０間半梁間３間半のつし２階建で入母屋造，桟瓦葺とし，北と東に庇がつく。東半をミセドマ，西半を居室とし，南に吹抜の土間と座敷が突出する。正面は１階西寄りを出格子とし，塗籠の２階には虫籠窓を開き，出桁造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004381"},{"id":"00004382","register_sub_id":"101","register_pk":"105372","name":"西條合資会社旧店舗土蔵","kana":"さいじょうごうしがいしゃきゅうてんぽどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市長野町13-11","lat":34.44916075,"lng":135.57042751,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積28㎡","structure_material":"土蔵造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0310","desc":"主屋の西に接続する土蔵造の平屋建である。桁行３間梁間２間の東西棟で，屋根を切妻造，桟瓦葺とする。切石の基礎上に建ち，外壁は白漆喰塗で，腰は縦羽目板張である。南側に両開土戸を釣込んだ戸口を設け，主屋から縁が接続する。北面には小庇付の窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004382"},{"id":"00005758","register_sub_id":"101","register_pk":"106746","name":"芝川ビルディング","kana":"しばかわびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区伏見町3-3-3","lat":34.689056,"lng":135.501831,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建、建築面積349㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0382","desc":"御堂筋から東に入ったブロックの北西隅に建つ。鉄筋コンクリート造４階建地階付で，腰を竜山石，上部はスクラッチタイル貼とし，３階軒部にスパニッシュ瓦を葺く。設計は渋谷五郎と本間乙彦。古代マヤ・インカの細部装飾を採入れたアールデコ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005758"},{"id":"00001528","register_sub_id":"101","register_pk":"102518","name":"船場ビルディング","kana":"せんばびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区淡路町2-5-8","lat":34.68710787,"lng":135.5041779,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート地上5階地下1階建、建築面積717㎡","structure_material":"鉄筋コンクリート地上5階地下1階建","registered":"2000.02.15(平成12.02.15)","register_no":"27 － 0087","desc":"御堂筋近くに建つ鉄筋コンクリート造５階建の住宅兼事務所ビル。外観はタイル張オフィスビルの意匠になるが，内部中央に細長いパティオ風の中庭を設けて吹き抜けとし，その周囲各階に回廊を巡らす特色ある造りとする。設計は村上徹一の建築事務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001528"},{"id":"00016680","register_sub_id":"101","register_pk":"579164","name":"天満屋ビル","kana":"てんまやびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市港区海岸通一丁目5-1","lat":34.652522,"lng":135.430086,"geo_status":"db","era":"昭和10年／昭和22年・平成11年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積151㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2026.07.09(令和8.07.09)","register_no":"27 - 0971","desc":"築港大道路に南面して建つ旧回漕業の事務所兼住宅。設計は小笠原祥光。鉄筋コンクリート造3階建、外壁はスクラッチタイル貼とする。南西隅にアールを付け、玄関脇の垂直壁、水平性を示す庇など幾何学的な意匠の外観で、昭和戦前の流行を伝える事務所ビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016680"},{"id":"00014053","register_sub_id":"101","register_pk":"508313","name":"丼池繊維会館","kana":"どぶいけせんいかいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区久太郎町三丁目19","lat":34.68089167,"lng":135.50260833,"geo_status":"db","era":"大正11年／昭和30年以降改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄筋コンクリート造3階地下1階建、建築面積191㎡","structure_material":"鉄筋コンクリート造3階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0829","desc":"南船場丼池筋の交差点に建つ鉄筋コンクリート造地上三階地下一階建のテナントビル。外壁の二、三階はタイル張、隅を几帳面状に丸め深い軒下にデンティルを廻し窓間に装飾を付す。内部は改変が大きいが階段廻り等に当初の意匠が残る。地域の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014053"},{"id":"00002153","register_sub_id":"101","register_pk":"103143","name":"中内眼科医院","kana":"なかうちがんかいいん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府富田林市富田林町146","lat":34.50038979,"lng":135.60339942,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積286㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2001.04.24(平成13.04.24)","register_no":"27 － 0134","desc":"富田林重伝建地区に近い堺町筋の角地に建つ。当初，国分銀行の本社屋として建設。ＲＣ造３階建で，隅部に玄関を設ける。１階壁面に大型の半円アーチ窓，２階に半円錐窓台付の上げ下げ窓を配す。町屋建築が多いこの地域で，近代的景観を際だたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002153"},{"id":"00008513","register_sub_id":"101","register_pk":"134909","name":"南海ビル","kana":"なんかいびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区難波5-12","lat":34.66469613,"lng":135.50104338,"geo_status":"db","era":"昭和7年／昭和32年・昭和55年・平成21年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄骨鉄筋コンクリート造7階一部8階地下2階建、建築面積5915㎡、装飾塔付","structure_material":"鉄骨鉄筋コンクリート造7階一部8階地下2階建","registered":"2011.01.26(平成23.01.26)","register_no":"27 － 0541","desc":"御堂筋南端に位置する南海難波駅のターミナルビル。ＳＲＣ造八階地下二階建。角を曲線で処理し、飾り壺を戴くコリント式の壁付円柱とアーチの連続で壁面を構成する。エントランス上部や屋上の装飾塔など随所に装飾が配され、華やかで格調高い外観を実現する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008513"},{"id":"00003464","register_sub_id":"101","register_pk":"104454","name":"南天苑本館","kana":"なんてんえんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府河内長野市天見158","lat":34.397423,"lng":135.594589,"geo_status":"db","era":"大正2／昭和10移築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積608㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0257","desc":"Ｌ字型平面の木造２階建，桟瓦葺，入母屋造の料理旅館建築。大正２年に堺市に建設され，昭和１０年に現在地に移築されている。設計は辰野片岡事務所による。内部は客室を中心とし，１階東南隅には大広間を設ける。近代の大規模和風建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003464"},{"id":"00014055","register_sub_id":"101","register_pk":"508315","name":"原田産業大阪本社ビル","kana":"はらださんぎょうおおさかほんしゃびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区南船場二丁目9","lat":34.67693889,"lng":135.50371944,"geo_status":"db","era":"昭和3年／同40年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積143㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0831","desc":"南船場の中心部に建つ鉄筋コンクリート造二階建の商社本社ビル。古典様式をアレンジした特徴的な外観は石張とモルタル洗出仕上。内部は階段室の吹抜両脇に部屋を配し、内装に日華石やオーク材等良質な材を用いる。小規模だが豊かな空間構成の近代ビル建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014055"},{"id":"00012218","register_sub_id":"101","register_pk":"353018","name":"播谷商店主屋","kana":"はりたにしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目53-1","lat":34.633791,"lng":135.513644,"geo_status":"db","era":"昭和4年頃／平成27年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"27-713","desc":"第二次市域拡張で大阪市に編入された地に建つ。主屋は南北棟の広間棟の左右に東西棟の玄関棟、仏間棟が連なる構成で、それぞれ入母屋造、切妻造、寄棟造とする。広間棟の座敷八畳は東・南面を庭に向かって開く。意匠を凝らした中廊下式の近代和風住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012218"},{"id":"00012219","register_sub_id":"101","register_pk":"353019","name":"播谷商店店舗","kana":"はりたにしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目53-1","lat":34.633757,"lng":135.513474,"geo_status":"db","era":"昭和4年頃／昭和50年代後半改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"27-714","desc":"敷地の南西隅に建ち、二方を街路に面する質屋店舗。南北棟の起り屋根を桟瓦で葺き、腰部を花崗岩貼、窓には格子を入れ、二階壁面は黒色タイル貼で軒まで黒漆喰で塗込める。内部は南西端に二方向に入口を持つ土間とする。堅牢さを表現した店舗建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012219"},{"id":"00012220","register_sub_id":"101","register_pk":"353020","name":"播谷商店土蔵","kana":"はりたにしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目53-1","lat":34.633834,"lng":135.513494,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"27-715","desc":"店舗の北側に建ち、南面庇で蔵前として接する。建築面積五六平方メートル、東西棟の土蔵造二階建、切妻造桟瓦葺で、外壁は腰花崗岩板貼、一階部分竪板張で、上部は軒まで白漆喰で塗込める。質屋店舗に欠かせない土蔵で、地域の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012220"},{"id":"00012221","register_sub_id":"101","register_pk":"353021","name":"播谷商店門及び塀","kana":"はりたにしょうてんもんおよびへい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目53-1","lat":34.63367667,"lng":135.51378468,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"門 木造、瓦葺一部銅板葺、間口3.8m 塀 コンクリート造、総延長41m","structure_material":"門 木造","registered":"2018.03.27(平成30.03.27)","register_no":"27-716","desc":"敷地南面に門を開き、東面へ矩折れに塀を設ける。塀は石積基壇の上にコンクリート塀を立ち上げ、約三メートル間隔に柱型を設け、上部の桁状部分を支え、その上に低い板塀を立てるなど、意匠性に富み地域の歴史的景観に寄与する門と塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012221"},{"id":"00013143","register_sub_id":"101","register_pk":"368388","name":"針中野中野鍼裏門","kana":"はりなかのなかのはりうらもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61840833,"lng":135.53513333,"geo_status":"db","era":"昭和13年頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造、銅瓦葺、間口2.3m、西方潜戸付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0785","desc":"敷地北辺東隅に北面して建ち、庭園に続く経路に開く門。表門に類似した特異な形式の一間一戸、脇戸付。屋根に銅瓦を用い、小壁に筬欄間、背面側天井を格天井とするなど相違点はあるが、表門に比肩する堂々としたつくりで、北東隅の敷地景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013143"},{"id":"00013142","register_sub_id":"101","register_pk":"368387","name":"針中野中野鍼表門","kana":"はりなかのなかのはりおもてもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.6182,"lng":135.53475,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、間口2.2m、東方潜戸付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0784","desc":"旧応接処と文書蔵の間に南面して建つ。高塀に切妻屋根が突出したような特異な形式の一間一戸、脇戸付の門。親柱上に肘木を十字に組み、前後に延びる桁を載せて梁で繋ぐ。背面は屋根を葺下ろし、鏡天井を張る。歴史ある当院に相応しい堂々とした門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013142"},{"id":"00013138","register_sub_id":"101","register_pk":"368383","name":"針中野中野鍼旧応接処","kana":"はりなかのなかのはりきゅうおうせつしょ","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61823889,"lng":135.5347,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造一部土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"木造一部土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0780","desc":"鍼の処の南西に接続し、東面して建つもと賓客用施設。木造一部土蔵造二階建、本瓦葺で、東面北側に入母屋玄関を付す。外壁は真壁漆喰塗で腰を竪板張とするが、南面は漆喰を軒裏まで塗込めて土蔵造風に仕上げる。並び建つ土蔵と調和した街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013138"},{"id":"00013139","register_sub_id":"101","register_pk":"368384","name":"針中野中野鍼主屋","kana":"はりなかのなかのはりしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61835,"lng":135.53491111,"geo_status":"db","era":"明治43年／昭和13年頃増築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0781","desc":"敷地北辺中央に北面して建つ入母屋造桟瓦葺で、四周に下屋を廻し、東面に便所と新館が突出する。外壁は軒裏まで漆喰で塗込めて虫籠窓を穿ち、腰に竪板を張る。内部は西を土間、東を居室とし、病室用の新館は床を設けた上質なつくり。屋敷構の中核を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013139"},{"id":"00013137","register_sub_id":"101","register_pk":"368382","name":"針中野中野鍼鍼の処","kana":"はりなかのなかのはりはりのところ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61832778,"lng":135.53473611,"geo_status":"db","era":"江戸末期／明治43年・平成15年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、金属板葺、建築面積102㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0779","desc":"針中野に位置する鍼灸院。敷地北西に北面して建つ。大和棟風で、正背面に下屋を付す。外壁は漆喰塗で、腰を竪板張とする。内部は東に通り土間、西に二列四室を配し、その南を旧応接処に繋がる縁とする。江戸末期の街路景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013137"},{"id":"00013141","register_sub_id":"101","register_pk":"368386","name":"針中野中野鍼物置蔵","kana":"はりなかのなかのはりものおきくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.61820278,"lng":135.53485556,"geo_status":"db","era":"明治43年／平成7年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0783","desc":"文書蔵の東に東面して建つ。土蔵造二階建、東西棟の金属板葺で、外壁は漆喰塗で軒裏を壁面より張り出して塗込め、腰を竪板張とする。内部は上下階とも一室で、壁を漆喰で仕上げ、和小屋組とする。妻を見せる建物が並ぶ敷地南辺の景観に変化を加えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013141"},{"id":"00013140","register_sub_id":"101","register_pk":"368385","name":"針中野中野鍼文書蔵","kana":"はりなかのなかのはりもんじょくら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市東住吉区針中野三丁目9他","lat":34.618225,"lng":135.5348,"geo_status":"db","era":"明治35年／平成7年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"27 － 0782","desc":"敷地南辺中央に北面して建つ。土蔵造桟瓦葺で、外壁は漆喰で軒裏まで塗込めて鉢巻一段を廻し、腰を竪板張とする。内部は一階を前後二室に分け、二階は一室とする。和小屋組とし、棟から桁にかけて野地板を流板に張る。表門回りの景観を重厚に演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013140"},{"id":"00003456","register_sub_id":"101","register_pk":"104446","name":"廣海家住宅主屋","kana":"ひろうみけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町５６９他","lat":34.44891859,"lng":135.35450793,"geo_status":"db","era":"文久元","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積641㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0249","desc":"回船問屋の本宅。旧海岸沿いに広大な敷地を構える。主屋は間口１８間半の長大な町家で，桁行９間，梁間６間の中央部の両側にそれぞれ梁間４間の店(桁行５間)と座敷部(桁行４間半)を並べた平面。店部分を除き改造は少ない。ニワの梁組は豪壮で見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003456"},{"id":"00014056","register_sub_id":"101","register_pk":"508316","name":"フジカワビル","kana":"ふじかわびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市中央区瓦町一丁目7-1","lat":34.685825,"lng":135.50674444,"geo_status":"db","era":"昭和28年／同44年・平成28年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄筋コンクリート造5階地下1階建、建築面積153㎡","structure_material":"鉄筋コンクリート造5階地下1階建","registered":"2021.10.14(令和3.10.14)","register_no":"27 - 0832","desc":"堺筋に西面して建つ鉄筋コンクリート造地上五階地下一階建オフィスビル。二～四階正面を内窓付ガラスブロック積とし、両脇に小バルコニーを設けて陰影を演出。機能的な平面計画や階段等の随所に村野による繊細な意匠を凝らす。小規模だが都市部の景観に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014056"},{"id":"00002798","register_sub_id":"101","register_pk":"103788","name":"伏見ビル","kana":"ふしみびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区伏見町2-21-1","lat":34.688988,"lng":135.505737,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建、建築面積198㎡","structure_material":"鉄筋コンクリート造3階一部4階建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0178","desc":"大阪船場の中心部にある鉄筋コンクリート造３階建のビル。設計は辰野片岡事務所出身の長田岩次郎。角地に建ち，外観はコーナーを隅丸とし，３階の窓上に飾り丸窓，交差点に面する北西隅の２，３階に水平リブ状の飾り線を付けるなど変化に富んだ外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002798"},{"id":"00000300","register_sub_id":"101","register_pk":"101290","name":"三木楽器","kana":"みきがっき","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区北久宝寺町3-3-4","lat":34.67988285,"lng":135.50166257,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造地上4階地下1階建，建築面積468㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"1997.09.03(平成9.09.03)","register_no":"27 － 0023","desc":"鉄筋コンクリート造，地上４階地下１階建の楽器店。設計は増田建築事務所，施工は鴻池組で，ドイツの楽器店を模したと伝える。大正期の都市部における中層商業ビルの好例で，外壁をタイル張りとして縦の線を強調した外観によく時代の特徴があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000300"},{"id":"00014872","register_sub_id":"101","register_pk":"519132","name":"御堂ビルディング","kana":"みどうびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市中央区本町四丁目27-12他","lat":34.68408056,"lng":135.50016667,"geo_status":"db","era":"昭和40年","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄骨鉄筋コンクリート造地上9階地下4階建、建築面積3，442㎡、塔屋付","structure_material":"鉄骨鉄筋コンクリート造地上9階地下4階建","registered":"2024.03.06(令和6.03.06)","register_no":"27 - 0899","desc":"御堂筋と本町通の交差点角に建つオフィスビル。設計は竹中工務店設計部。センターコアを採用し、フルウェブ梁や軽量コンクリートなど当時の技術を駆使し大スパン構造を実現。単窓を繰返した壁面に茶、灰、土の３色の磁器タイル貼で格調高い外観に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014872"},{"id":"00001435","register_sub_id":"101","register_pk":"102425","name":"ミナミ株式会社（旧川崎貯蓄銀行福島出張所）","kana":"みなみかぶしきがいしゃ（きゅうかわさきちょちくぎんこうふくしましゅっちょうじょ）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市福島区福島5-17-7","lat":34.695042,"lng":135.484879,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート地上2階地下1階建、建築面積206㎡","structure_material":"鉄筋コンクリート地上2階地下1階建","registered":"1999.11.18(平成11.11.18)","register_no":"27 － 0079","desc":"川崎銀行系の建築を数多く手がけた矢部又吉の設計による小品。正面に４本のフルーティング付きイオニア式ジャイアント・オーダーを配し，端部を角型ピラスターで納める。敷地形状に対応してファサードに緩やかな凸曲面状のカーブを付けている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001435"},{"id":"00007398","register_sub_id":"101","register_pk":"108380","name":"八木家住宅主屋","kana":"やぎけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市三日市町1109","lat":34.437973,"lng":135.570343,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0519","desc":"高野街道に西面して建つ。間口８間半規模の平入町家で、切妻造桟瓦葺とし、正面に本瓦葺の深い軒を付ける。中央南寄りに大戸口を開く。内部は南半部を土間のニワなどとし、北半部にザシキやミセなどを配した。旧三日市宿にあって町家の伝統様式をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007398"},{"id":"00007399","register_sub_id":"101","register_pk":"108381","name":"八木家住宅土蔵","kana":"やぎけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市三日市町1109","lat":34.4380584,"lng":135.57030326,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0520","desc":"主屋の北側に建ち、通りに妻を見せる。切妻造本瓦葺の土蔵造２階建。外壁は白漆喰仕上げとし、腰に杉の焼板を張る。通り側の妻には窓を各階に開け、銅板の扉を吊り、下階の窓には漆喰仕上げの庇を付ける。主屋とともに旧宿場町の街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007399"},{"id":"00001720","register_sub_id":"101","register_pk":"102710","name":"山内ビル","kana":"やまうちびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区土佐堀1-1-5","lat":34.69242414,"lng":135.49561934,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"鉄筋コンクリート造地上4階地下1階建、建築面積75㎡","structure_material":"鉄筋コンクリート造地上4階地下1階建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0092","desc":"法律事務所として建設された事務所建築で外壁は褐色タイル貼り。一階東端の入口を花崗岩で縁取り二階の窓台装飾を垂らしてアーチの中心飾りとする。一階中央及び西にも同様なデザインの窓を設け二・三階の縦長窓の縦枠を一階から連続させて縦の線を強調する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001720"},{"id":"00003453","register_sub_id":"101","register_pk":"104443","name":"吉村家住宅主屋","kana":"よしむらけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町12-7","lat":34.44886328,"lng":135.3552178,"geo_status":"db","era":"江戸中期／江戸末期増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積460㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0246","desc":"江戸時代油屋，金融業を営んだ商家。主屋の北側主要部は古く，１８世紀中頃まで遡ると見られる。貝塚では町家の座敷は上手側背後に増築されるのが通例であるが，ここでは幕末期に下手側（南側）に増築されているのが珍しい。増築座敷の意匠も優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003453"},{"id":"00003282","register_sub_id":"101","register_pk":"104272","name":"利齋家住宅主屋","kana":"りさいけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-3","lat":34.44984707,"lng":135.35744593,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積253㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0227","desc":"利齋家はト半役所北側の角地で薬種を商った貝塚寺内町の有力町人である。主屋は比較的梁間が狭く，切妻造の屋根は棟を挟んだ３間を一段高く綴葺とするが小屋は一連の登梁で段差とは関係がない。１７世紀まで遡る可能性があるが，それだけに後の改造も大きい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003282"},{"id":"00003284","register_sub_id":"101","register_pk":"104274","name":"利齋家住宅土蔵","kana":"りさいけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-3","lat":34.44997,"lng":135.357407,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積127㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0229","desc":"主屋西側に接して建てられた２階建の袖蔵。梁間は２間と標準的であるが，桁行は１０間の長大な蔵で，内部は南北５間の２室に区切られ，南半を薬種，北半を衣装や道具の倉庫に使われていた。主屋と同様，兵庫県南部地震後本瓦から桟瓦に葺き替えられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003284"},{"id":"00011350","register_sub_id":"101","register_pk":"209187","name":"リバーサイドビルディング","kana":"りばーさいどびるでぃんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市北区中之島三丁目45他","lat":34.691798,"lng":135.493279,"geo_status":"db","era":"昭和40","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"鉄筋コンクリート造5階地下1階建、建築面積175㎡、塔屋付","structure_material":"鉄筋コンクリート造5階地下1階建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0648","desc":"土佐堀川に面して建つ横長平面の事務所建築。設計は岸田日出刀。高速道路の構造を引用したと伝え、構造壁を集約し、正背面に全長分の窓を配する明快な構成とする。妻壁は淡陶タイルでモザイク状に飾る。インターナショナルスタイルの事務所建築の秀作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011350"},{"id":"00013615","register_sub_id":"101","register_pk":"504986","name":"今村家住宅貸店舗","kana":"いまむらけじゅうたくかしてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県丹波篠山市西町字柚ノ木64-4他","lat":35.07525556,"lng":135.21049444,"geo_status":"db","era":"昭和8年／平成21年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"28 － 0745","desc":"陶々菴南側の道路拡幅に伴う隅切地に建つ。正方形の一角を落とした五角形平面の平屋に、Ｌ字形で入母屋造の二階を載せ、外壁は真壁造漆喰塗とする。内部は一階店舗は道路側に広く開口をとり、二階は座敷とする。特異な外観が伝統的な町並に変化を加える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013615"},{"id":"00010016","register_sub_id":"101","register_pk":"196163","name":"魚橋呉服店北土蔵","kana":"うおはしごふくてんきたどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市威徳寺町51-1","lat":34.84888121,"lng":134.70397637,"geo_status":"db","era":"大正14頃","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0581","desc":"店舗兼主屋の東後方に建ち、土蔵造二階建、桁行八・三メートル梁間三・九メートル、切妻造本瓦葺である。平面は南北二室に分かれ、双方に戸口を設けて庇を付ける。外壁漆喰塗で鉢巻を廻らし、腰に竪板や割竹を詰打ちとする。南土蔵とともに屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010016"},{"id":"00010014","register_sub_id":"101","register_pk":"196161","name":"魚橋呉服店店舗兼主屋","kana":"うおはしごふくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県姫路市威徳寺町51-1","lat":34.84895468,"lng":134.70381699,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階建、瓦葺、建築面積147㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0579","desc":"野里街道に西面する二階建町家で南主屋と並び建つ。正面二階は出桁造で軒蛇腹まで塗込め、ガラス窓を設ける。前寄りを土間のミセと畳敷のミセノマとして格天井を張り、中央はもと吹抜で二階に高欄を残す。商工業で栄えた野里の街並を伝える大型の商家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010014"},{"id":"00010015","register_sub_id":"101","register_pk":"196162","name":"魚橋呉服店南主屋","kana":"うおはしごふくてんみなみしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市威徳寺町50","lat":34.84887898,"lng":134.70376804,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積132㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0580","desc":"北隣に接する店舗兼主屋より軒が低く、本瓦を葺く。正面二階は出桁造で、垂木まで塗込め、虫籠窓を並べる。一階南寄りに土間を通し、手前に車庫、奥にナカノマを配し、坪庭を挟んで後方に離れ座敷を接続する。店舗兼主屋とともに野里の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010015"},{"id":"00010017","register_sub_id":"101","register_pk":"196164","name":"魚橋呉服店南土蔵","kana":"うおはしごふくてんみなみどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県姫路市威徳寺町50","lat":34.84881409,"lng":134.7039292,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"28 － 0582","desc":"南主屋の東後方に南北棟で建つ。土蔵造二階建、桁行四・六メートル梁間三・三メートル、切妻造本瓦葺で、南端に漬物蔵を附属する。外壁漆喰塗で腰を海鼠壁とする。西面南寄りの戸口に掛子塗の扉を開いて庇を付し、直上にも窓を穿つ。家財を収めた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010017"},{"id":"00000999","register_sub_id":"101","register_pk":"101989","name":"海岸ビル","kana":"かいがんびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県神戸市中央区海岸通３","lat":34.686574,"lng":135.19066183,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"鉄筋コンクリート造地下１階地上４階建，５階以上部分を除く，建築面積1185㎡","structure_material":"鉄筋コンクリート造地下１階地上４階建","registered":"1998.12.11(平成10.12.11)","register_no":"28 － 0039","desc":"旧神戸居留地バンド（海岸通り）を代表する建造物。三井物産神戸支店ビルとして建てられた。設計は河合浩蔵。鉄筋コンクリート造４階建のオフィスビルで，ルネサンス様式の骨格にセセッションの細部が随所に採り入れられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000999"},{"id":"00003465","register_sub_id":"101","register_pk":"104455","name":"海岸ビルヂング","kana":"かいがんびるぢんぐ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市中央区海岸通3-1-5","lat":34.685947,"lng":135.186859,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"煉瓦造3階建、建築面積682㎡","structure_material":"煉瓦造3階建","registered":"2003.07.01(平成15.07.01)","register_no":"28 － 0122","desc":"煉瓦造３階建の事務所建築で，設計は河合浩蔵，施工は旗手組。戦災により内装のかなりの部分と外部装飾の一部を失っているが，唐破風状の曲線を取り入れるなど独特の細部意匠が特徴である。現在では店舗，事務所，ギャラリーなどとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003465"},{"id":"00016563","register_sub_id":"101","register_pk":"574925","name":"旧尾上家住宅（小倉屋）主屋","kana":"きゅうおのえけじゅうたく（こくらや）てんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市堺町30","lat":34.83817194,"lng":134.70058,"geo_status":"db","era":"寛政7年（1795）／大正前期・昭和後期・令和6年改修","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積142㎡","structure_material":"木造平屋一部2階建","registered":"2026.02.10(令和8.02.10)","register_no":"28 - 0850","desc":"野里街道に西面する旧金物商の主屋。つし二階建切妻造平入本瓦葺で棟高を南北で違え、南棟に煙出を載せる。北に2列の部屋を並べ、南は広い通り土間とする。外壁漆喰塗で三箇所の虫籠窓を開け、建ちの低い表構えが近世姫路城下町の様相を伝える貴重な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016563"},{"id":"00013845","register_sub_id":"101","register_pk":"507804","name":"旧駿河屋","kana":"きゅうするがや","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬830","lat":34.79699444,"lng":135.24748333,"geo_status":"db","era":"大正15年／令和2年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積42㎡","structure_material":"木造3階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0748","desc":"有馬温泉にある元竹細工の工房で、湯本坂に北面して建つ。木造三階建で、元は一階は工房、二階は住居、三階は床付座敷で湯治客の貸間とした。外壁は杉皮張で化粧垂木に杉丸太を用い、北側座敷は北西面に広く開口をとる。戦前の湯本坂界隈の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013845"},{"id":"00011773","register_sub_id":"101","register_pk":"210789","name":"旧高砂銀行本店（高砂商工会議所会館）","kana":"きゅうたかさごぎんこうほんてん（たかさごしょうこうかいぎしょかいかん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県高砂市高砂町字北本町1104他","lat":34.746596,"lng":134.802323,"geo_status":"db","era":"昭和7年／昭和55年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積300㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0660","desc":"本町通りに面して建つ銀行建築。鉄筋コンクリート造二階建で、正面中央を出入口とし、両脇にイオニア式オーダーの柱を立て、頂部にパルメット文様、持送りを並べたエンタブレチュアを廻らすなど外観は古典主義様式に倣い、当時の小規模銀行建築の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011773"},{"id":"00011774","register_sub_id":"101","register_pk":"210790","name":"旧高砂通運本社屋","kana":"きゅうたかさごつううんほんしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県高砂市高砂町字鍛冶屋町1396","lat":34.747823,"lng":134.801196,"geo_status":"db","era":"昭和14年／平成27年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積53㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"28-0661","desc":"商店街の角地に建つ事務所建築。木造二階建で通りに面した外壁を煉瓦積スクラッチタイル貼とする。屋根は緩勾配の寄棟造鉄板葺。平坦な壁面、壁頂部の水平ライン、矩形の開口部を各面に設けるなどモダニズム建築に通ずる外観意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011774"},{"id":"00013844","register_sub_id":"101","register_pk":"507803","name":"旧摩耶観光ホテル","kana":"きゅうまやかんこうほてる","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区畑原字ノタ山344","lat":34.72763056,"lng":135.21277222,"geo_status":"db","era":"昭和5年／昭和36年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階地下2階建、陸屋根、建築面積901㎡","structure_material":"鉄筋コンクリート造2階地下2階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0747","desc":"摩耶山南麓中腹に建つ。鉄筋コンクリート造Ｌ字形平面の四層各階に水平庇を廻らして曲面を強調し、大きな開口を開ける。内部の大ホールや大食堂は、大梁と柱形で大空間を分節し、舞台等にアールデコ調意匠をみせる。かつての山上リゾート施設の有様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013844"},{"id":"00011990","register_sub_id":"101","register_pk":"354926","name":"旧大和屋旅館","kana":"きゅうやまとやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字中409","lat":35.626036,"lng":134.808864,"geo_status":"db","era":"昭和2年／昭和40年頃改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造3階建、瓦葺、建築面積59㎡","structure_material":"木造3階建","registered":"2017.10.27(平成29.10.27)","register_no":"28-672","desc":"湯の里通りに北面する木造三階建の旅館。間口三間、切妻造とし、二、三階正面側は床の間、床脇、付書院を備えた客室で、建具や欄間に繊細な意匠を見せる。正面に縁を廻らし、ガラス戸を建て、内に高欄を設けた外観が、温泉街の街路景観を良好に形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011990"},{"id":"00004178","register_sub_id":"101","register_pk":"105168","name":"日下旅館","kana":"くさかりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県朝来市生野町口銀谷1958","lat":35.16335762,"lng":134.78944091,"geo_status":"db","era":"明治43／大正10増築","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建一部3階建、瓦葺、建築面積539㎡","structure_material":"木造2階建一部3階建","registered":"2004.06.09(平成16.06.09)","register_no":"28 － 0173","desc":"ＪＲ生野駅前に建つ旅館建築。南を正面とする木造２階建で，口の字型に近い平面とし，南東部の３階建が大正の増築で，２階・３階には数寄屋風の座敷を配している。縁側の高欄や軒廻り小壁の鶴や雲を象った下地窓などに，和風旅館らしい造形要素がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004178"},{"id":"00010216","register_sub_id":"101","register_pk":"198049","name":"神戸ゴルフ倶楽部クラブハウス","kana":"こうべごるふくらぶくらぶはうす","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区六甲山町一ケ谷1-3","lat":34.75839,"lng":135.238059,"geo_status":"db","era":"昭和7／昭和29・昭和59改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積457㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"28 － 0595","desc":"日本最古のゴルフ場に建つクラブハウス。外観は下見板張の外壁に白色の上下窓や扉を並べ、内部はタイル貼の暖炉の東西に食堂や休憩室を、背面側にロッカー室を配する。内壁に高い腰パネルを張り、天井は化粧梁形を見せて板張とするなど洗練された意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010216"},{"id":"00010217","register_sub_id":"101","register_pk":"198050","name":"神戸ゴルフ倶楽部チェンバー","kana":"こうべごるふくらぶちぇんばー","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県神戸市灘区六甲山町北六甲4561-1他","lat":34.75994521,"lng":135.23688068,"geo_status":"db","era":"大正13／昭和28・昭和49改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積396㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"28 － 0596","desc":"大阪の青年実業家の社交場として建設された「サースディ倶楽部」を取得し、改修した宿泊施設。横長の建物で南面中央に玄関を配し、ロビーを介して東半を中廊下と宿泊室に間仕切り、西半を食堂や休憩室とする。屋根勾配を抑えた建ちの低い外観が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010217"},{"id":"00000706","register_sub_id":"101","register_pk":"101696","name":"神戸市立博物館（旧横浜正金銀行神戸支店）","kana":"こうべしりつはくぶつかん（きゅうよこはましょうきんぎんこうこうべしてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区京町24","lat":34.68726356,"lng":135.19307519,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上５階地下１階建，建築面積1775㎡","structure_material":"鉄筋コンクリート造一部鉄骨造地上５階地下１階建","registered":"1998.09.02(平成10.09.02)","register_no":"28 － 0026","desc":"正面に６本のドリス式の半円柱が建つ古典主義様式の建築。英国王立建築家協会会員桜井小太郎の設計になる。内部は博物館として改修されたが，二階吹き抜けの旧銀行業務室は大ホールとして天井とも保存された。神戸における様式建築の最後期の作品でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000706"},{"id":"00010322","register_sub_id":"101","register_pk":"199095","name":"神戸ポートタワー","kana":"こうべぽーとたわー","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市中央区波止場町7他","lat":34.682645,"lng":135.186723,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨造及び鉄筋コンクリート造、高さ108m、面積479㎡、展望室付","structure_material":"鉄骨造及び鉄筋コンクリート造","registered":"2014.12.19(平成26.12.19)","register_no":"28-0601","desc":"国際的貿易港である神戸港全体を眺望する中突堤を選び、港湾博物館施設として建設された。我が国で初の鋼管パイプフレーム構造で、直線材で曲面を構成した優美なつづみ形は今日でも斬新な意匠といえる。港神戸の象徴的な存在として、今なお広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010322"},{"id":"00013847","register_sub_id":"101","register_pk":"507806","name":"御所坊新館","kana":"ごしょぼうしんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬853","lat":34.79673889,"lng":135.24729722,"geo_status":"db","era":"昭和30年頃／昭和36年増築","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造及び鉄筋コンクリート造2階地下1階建、瓦葺一部銅板葺、建築面積351㎡","structure_material":"木造及び鉄筋コンクリート造2階地下1階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0750","desc":"本館の南斜面の上部に位置し、木造三階建部分と、鉄筋コンクリート造一層に木造二層分をのせる混構造部分からなる。外観は本館と同様モルタル吹付仕上で屋根は桟瓦葺。内装は和室を含め水平線や垂直線を重視した幾何学的な意匠で統一。敷地中程の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013847"},{"id":"00013848","register_sub_id":"101","register_pk":"507807","name":"御所坊土蔵","kana":"ごしょぼうどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬836-1","lat":34.79666944,"lng":135.24755,"geo_status":"db","era":"明治23年／昭和60年頃改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0751","desc":"本館及び新館とは道を挟んで南側の隣接地に位置する。土蔵造二階建切妻造妻入桟瓦葺。漆喰を鉢巻まで塗込め、腰壁を海鼠壁とする。内部は一室で一部吹抜。元は茶室付属の土蔵で茶道具や漆器を収納した。外観は当初を踏襲し、明治の温泉街の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013848"},{"id":"00013846","register_sub_id":"101","register_pk":"507805","name":"御所坊本館","kana":"ごしょぼうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県神戸市北区有馬町字有馬859他","lat":34.79676667,"lng":135.24695556,"geo_status":"db","era":"明治後期／昭和6年増築、昭和30年頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造3階建、瓦葺、建築面積527㎡","structure_material":"木造3階建","registered":"2021.06.24(令和3.06.24)","register_no":"28 － 0749","desc":"有馬温泉街の中心、滝川沿いに位置する。木造三階建桟瓦葺で、玄関のある東面は切妻造、その西にやや屈曲して入母屋造の昭和増築部が接続する。外壁は吹付仕上と真壁造漆喰仕上一部板張が混在。川沿いの眺望良好地に好んで建てられた旅館別館の姿を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013846"},{"id":"00010850","register_sub_id":"101","register_pk":"201685","name":"小林屋旅館","kana":"こばやしやりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕369","lat":35.625446,"lng":134.810065,"geo_status":"db","era":"昭和前期／昭和中期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階一部3階建、瓦葺、建築面積472㎡","structure_material":"木造2階一部3階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0620","desc":"川沿いの通りに面して建つ木造三階建旅館で、正面二階に客室、三階に広間を配し、開口を広め、庇を廻らせる。奥行の長い平面で最奥の二階建も客室とし、中間部に採光用の中庭と、小さめの内湯のみを設ける平面など、城崎温泉の伝統的な旅館形態をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010850"},{"id":"00011168","register_sub_id":"101","register_pk":"205275","name":"佐藤家及び西村家住宅","kana":"さとうけおよびにしむらけじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市中央町49-4他","lat":35.543929,"lng":134.822402,"geo_status":"db","era":"昭和2頃／昭和59・平成5改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階建、鋼板葺、建築面積210㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0651","desc":"北但馬地震後に耐火建築が強く推奨されるなか、駅前通りに面して建てられた三戸一体の鉄筋コンクリート造店舗併用住宅。、三戸それぞれに異なる立面デザインとし、各所にアーチやロンバルディア帯、メダイオンといった洋風意匠をちりばめ特徴ある外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011168"},{"id":"00010854","register_sub_id":"101","register_pk":"201689","name":"新かめや本館","kana":"しんかめやほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字愛宕279","lat":35.626095,"lng":134.810416,"geo_status":"db","era":"昭和34","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造3階建、瓦葺、建築面積206㎡","structure_material":"木造3階建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0624","desc":"河畔に建つ木造三階建旅館で平田雅哉の設計になる。正面階境に庇を廻らし、一階東寄りの玄関と二階西寄りに千鳥破風を配して外観を整える。玄関廻りに細格子の横長窓を配し、直線的で端正な意匠の座敷飾に朱塗の棚で趣を添えるなど、平田の作風の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010854"},{"id":"00009053","register_sub_id":"101","register_pk":"162413","name":"新港貿易会館（旧新港相互館）","kana":"しんこうぼうえきかいかん（きゅうしんこうそうごかん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区新港町8-2","lat":34.68454382,"lng":135.19888864,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造4階地下1階建、建築面積519㎡、塔屋付","structure_material":"鉄筋コンクリート造4階地下1階建","registered":"2011.10.28(平成23.10.28)","register_no":"28 － 0530","desc":"神戸の新港地区に建ち、建築面積５１９㎡、鉄筋コンクリート造四階地下一階建である。外壁はスクラッチタイル貼で、十字路に面した西南隅に出入口を開く。幾何学図形やアールデコ風の装飾など新しい意匠を巧みに取り入れた独創的な事務所ビル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009053"},{"id":"00016419","register_sub_id":"101","register_pk":"536486","name":"宝塚ゴルフ倶楽部クラブハウス","kana":"たからづかごるふくらぶくらぶはうす","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県宝塚市蔵人字深谷1391-1他","lat":34.78751111,"lng":135.34071667,"geo_status":"db","era":"昭和34年／昭和46年・平成8年増築、同24年改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造地上3階地下1階建、建築面積2，550㎡","structure_material":"鉄筋コンクリート造一部鉄骨造地上3階地下1階建","registered":"2025.11.17(令和7.11.17)","register_no":"28 - 0847","desc":"逆瀬川沿いのゴルフ場のクラブハウス。設計は村野藤吾を中心とした建設委員会。斜面地に建つ鉄筋コンクリート造一部鉄骨造、地上3階地下１階建。外周に軒を張出し、中央に塔屋を配す。水平性を強調しつつ、塔屋と組合わせた外観が、周囲の環境と調和を生む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016419"},{"id":"00014401","register_sub_id":"101","register_pk":"511390","name":"帝国信栄本社屋","kana":"ていこくしんえいほんしゃおく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区琴ノ緒町五丁目312-1他","lat":34.69563056,"lng":135.19473056,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造2階建、建築面積273㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"28 - 0788","desc":"三ノ宮駅北側の市街地に所在する商業ビル。鉄筋コンクリート造二階建、交差点に面する角を御影石縁取りと垂直性を強調した柱形でセセッションを取入れた正面入口とし、側壁は表現主義的な円柱意匠とする。営業室の柱には変形したイオニア式柱頭飾を付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014401"},{"id":"00006041","register_sub_id":"101","register_pk":"107026","name":"豊岡市役所南庁舎別館（旧兵庫縣農工銀行豊岡支店）","kana":"とよおかしやくしょみなみちょうしゃべっかん（きゅうひょうごけんのうこうぎんこうとよおかしてん）","category":"産業3次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市中央町11-22","lat":35.54362268,"lng":134.81992832,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積495㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"28 － 0252","desc":"北西の角地に北面して建ち，間口２７ｍ，奥行１４ｍの規模で，南面西端に付属室を，東端に金庫室を張り出す。正面中央を玄関とし，奥の事務室を２階まで吹抜けとする。外壁はタイル貼，腰及び四隅を石貼とし，正面にピラスターを並べ，重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006041"},{"id":"00004280","register_sub_id":"101","register_pk":"105270","name":"西尾家住宅酒蔵","kana":"にしおけじゅうたくさかぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.096832,"lng":135.138184,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積360㎡","structure_material":"土蔵造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0182","desc":"主屋の東南方に位置し，土蔵ギャラリーとともに屋敷地東辺を画する。桁行１１間梁間５間規模，南北棟，切妻造，桟瓦葺の仕込蔵の北方に，棟を落として物置（もと麹蔵）等を配する。酒造場の中核施設になり，敷地東面に長大な酒蔵景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004280"},{"id":"00004278","register_sub_id":"101","register_pk":"105268","name":"西尾家住宅新蔵二","kana":"にしおけじゅうたくしんぐらに","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.09708,"lng":135.137939,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積279㎡","structure_material":"土蔵造2階建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0180","desc":"茶室，部屋蔵・中蔵，新蔵一の西面に沿って南北に流れる水路を越えた拡張敷地に南北棟で建つ。桁行１２間梁間６間規模の大きな２階建酒蔵で，切妻造，桟瓦葺，妻入とし，街道側の北妻面には高い位置に水切を設け，西面には２段６列の小窓を整然と配置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004278"},{"id":"00004279","register_sub_id":"101","register_pk":"105269","name":"西尾家住宅土蔵ギャラリー","kana":"にしおけじゅうたくどぞうぎゃらりー","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県篠山市大山上699","lat":35.09674701,"lng":135.13796741,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積156㎡","structure_material":"土蔵造平屋一部2階建","registered":"2004.07.23(平成16.07.23)","register_no":"28 － 0181","desc":"主屋の南方にほぼ東西棟で建つ。桁行８間梁間５間規模，切妻造，桟瓦葺の平屋建で，現在は西尾本家の資料館として活用され，東半は展示ギャラリーとなっている。他の酒蔵と同様，基礎を花崗石積とし，腰を縦板張，上部を漆喰塗に仕上げ，軒裏まで塗込める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004279"}];
